uint IterateMandelbrot(float a, float b)
{
  float x;
  float y;
  float x2;
  float y2;
  x = (x2 = 0.0f);
  y = (y2 = 0.0f);
  float m2;
  int i;
  float h = 0.0;
  volatile int flag = 0;
  for (i = 0; i < 2048; i++)
  {
    if (flag == 1)
      continue;

    y = ((2.0f * x) * y) + b;
    x = (x2 - y2) + a;
    x2 = x * x;
    y2 = y * y;
    m2 = x2 + y2;
    if (m2 > 100.0f)
      flag = 1;

    h += 1.0;
  }

  h = (h + 1.0) - log2(.5 * log(m2));
  return (h / 100.0) * 256;
}

