void bounce(double *x, double *y, double *u, double *v)
{
  double W = 1.0f;
  double H = 1.0f;
  if ((*x) > W)
  {
    *x = (2 * W) - (*x);
    *u = -(*u);
  }

  if ((*x) < 0)
  {
    *x = -(*x);
    *u = -(*u);
  }

  if ((*y) > H)
  {
    *y = (2 * H) - (*y);
    *v = -(*v);
  }

  if ((*y) < 0)
  {
    *y = -(*y);
    *v = -(*v);
  }

}

