{
  const double r = (alpha * dt) / (dx * dx);
  const double r2 = 1.0 - (4.0 * r);
  #pragma omp parallel for
  for (int j = 0; j < n; ++j)
  {
    for (int i = 0; i < n; ++i)
    {
      u_tmp[i + (j * n)] = ((((r2 * u[i + (j * n)]) + (r * ((i < (n - 1)) ? (u[(i + 1) + (j * n)]) : (0.0)))) + (r * ((i > 0) ? (u[(i - 1) + (j * n)]) : (0.0)))) + (r * ((j < (n - 1)) ? (u[i + ((j + 1) * n)]) : (0.0)))) + (r * ((j > 0) ? (u[i + ((j - 1) * n)]) : (0.0)));
    }

  }

}

