  }

  for (i = 0; i < 1000; ++i)
  {
    logics[i] = 1;
  }

  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(&:bit_and)
  for (i = 0; i < 1000; ++i)
  {
    bit_and = bit_and & logics[i];
  }

  if (!bit_and)
  {
