    fprintf(stderr, "Error in BIT AND part 1.\n");
  }

  bit_and = 1;
  logics[1000 / 2] = 0;
  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(&:bit_and)
  for (i = 0; i < 1000; ++i)
  {
