int parallel_linear_search(int *arr, int size, int item)
{
  int index = size;
  #pragma omp parallel for shared(index)
  for (int i = 0; i < size; i++)
  {
    if (arr[i] == item)
    {
      if (i < index)
      {
        index = i;
      }

    }

  }

  if (index == size)
  {
    return -1;
  }

  return index;
}


double end()
{
  struct timespec *end_t = malloc(sizeof(struct timespec));
  clock_gettime(CLOCK_MONOTONIC, end_t);
  double time = (double) (end_t->tv_sec - start_t->tv_sec);
  time += ((double) (end_t->tv_nsec - start_t->tv_nsec)) / ((double) 1000000000);
  return time;
}

