int receive_float_message(float *num, int source, int tag)
{
  MPI_Status stat;
  tag = 0;
  *num = -1;
  MPI_Recv(num, 1, (MPI_Datatype) 0x4c00040a, source, tag, (MPI_Comm) 0x44000000, &stat);
  if ((*num) < 0)
  {
    printf("ERROR - received float is: %f\tTerminate Execution\n", *num);
    return 0;
  }

  return 1;
}


