  for (int i = 0; i < k; i++)
  {
    w[i] = 0;
    for (int j = 0; j < n; j++)
    {
      w[i] += (datapoint[j] - mu[i][j]) * (datapoint[j] - mu[i][j]);
    }

  }

  double min = 9999999;
  int ans = 0;
  for (int i = 0; i < k; i++)
  {
    if (w[i] < min)
    {
      min = w[i];
      ans = i;
    }

  }

  return ans;
}

