void OMP_GaussianBlur(double *u, double Ksigma, int stepCount)
{
  double lambda = (Ksigma * Ksigma) / ((double) (2 * stepCount));
  double nu = ((1.0 + (2.0 * lambda)) - sqrt(1.0 + (4.0 * lambda))) / (2.0 * lambda);
  int x;
  int y;
  int z;
