  double boundryScale = 1.0 / (1.0 - nu);
  double postScale = pow(nu / lambda, (double) (3 * stepCount));
  for (step = 0; step < stepCount; step++)
  {
    for (y = 0; y < OMP_yMax; y++)
    {
      for (z = 0; z < OMP_zMax; z++)
      {
        u[OMP_Index(0, y, z)] *= boundryScale;
      }

    }

    for (x = 1; x < OMP_xMax; x++)
    {
      for (y = 0; y < OMP_yMax; y++)
      {
        for (z = 0; z < OMP_zMax; z++)
        {
          u[OMP_Index(x, y, z)] += u[OMP_Index(x - 1, y, z)] * nu;
        }

      }

    }

    for (y = 0; y < OMP_yMax; y++)
    {
      for (z = 0; z < OMP_zMax; z++)
      {
        u[OMP_Index(0, y, z)] *= boundryScale;
      }

    }

    for (x = OMP_xMax - 2; x >= 0; x--)
    {
      for (y = 0; y < OMP_yMax; y++)
      {
        for (z = 0; z < OMP_zMax; z++)
        {
          u[OMP_Index(x, y, z)] += u[OMP_Index(x + 1, y, z)] * nu;
        }

      }

    }

    for (x = 0; x < OMP_xMax; x++)
    {
      for (z = 0; z < OMP_zMax; z++)
      {
        u[OMP_Index(x, 0, z)] *= boundryScale;
      }

    }

    for (x = 0; x < OMP_xMax; x++)
    {
      for (y = 1; y < OMP_yMax; y++)
      {
        for (z = 0; z < OMP_zMax; z++)
        {
          u[OMP_Index(x, y, z)] += u[OMP_Index(x, y - 1, z)] * nu;
        }

      }

    }

    for (x = 0; x < OMP_xMax; x++)
    {
      for (z = 0; z < OMP_zMax; z++)
      {
        u[OMP_Index(x, OMP_yMax - 1, z)] *= boundryScale;
      }

    }

    for (x = 0; x < OMP_xMax; x++)
    {
      for (y = OMP_yMax - 2; y >= 0; y--)
      {
        for (z = 0; z < OMP_zMax; z++)
        {
          u[OMP_Index(x, y, z)] += u[OMP_Index(x, y + 1, z)] * nu;
        }

      }

    }

    for (x = 0; x < OMP_xMax; x++)
    {
      for (y = 0; y < OMP_yMax; y++)
      {
        u[OMP_Index(x, y, 0)] *= boundryScale;
      }

    }

    for (x = 0; x < OMP_xMax; x++)
    {
      for (y = 0; y < OMP_yMax; y++)
      {
        for (z = 1; z < OMP_zMax; z++)
        {
          u[OMP_Index(x, y, z)] = u[OMP_Index(x, y, z - 1)] * nu;
        }

      }

    }

    for (x = 0; x < OMP_xMax; x++)
    {
      for (y = 0; y < OMP_yMax; y++)
      {
        u[OMP_Index(x, y, OMP_zMax - 1)] *= boundryScale;
      }

    }

    for (x = 0; x < OMP_xMax; x++)
    {
      for (y = 0; y < OMP_yMax; y++)
      {
        for (z = OMP_zMax - 2; z >= 0; z--)
        {
          u[OMP_Index(x, y, z)] += u[OMP_Index(x, y, z + 1)] * nu;
        }

      }

    }

  }

  #pragma omp parallel for private(y,z)
  for (x = 0; x < OMP_xMax; x++)
  {
    for (y = 0; y < OMP_yMax; y++)
    {
      for (z = 0; z < OMP_zMax; z++)
      {
        u[OMP_Index(x, y, z)] *= postScale;
      }

    }

  }

}


