  logics[1000 / 2] = 0;
  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(&:bit_and)
  for (i = 0; i < 1000; ++i)
  {
    bit_and = bit_and & logics[i];
  }

  if (bit_and)
  {
    result++;
    fprintf(stderr, "Error in BIT AND part 2.\n");
  }

  for (i = 0; i < 1000; i++)
  {
