  {
    bit_or = bit_or | logics[i];
  }

  if (bit_or)
  {
    result++;
    fprintf(stderr, "Error in BIT OR part 1\n");
  }

  bit_or = 0;
  logics[1000 / 2] = 1;
  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(|:bit_or)
  for (i = 0; i < 1000; ++i)
  {
    bit_or = bit_or | logics[i];
  }

