  {
    matrix[i] = malloc(dimension * (sizeof(TYPE)));
  }

  srand((time(0) + clock()) + rand);
  for (int i = 0; i < dimension; i++)
  {
    for (int j = 0; j < dimension; j++)
    {
      matrix[i][j] = 0;
    }

