  for (i = 1; i <= 1000; i++)
  {
    sum = sum + i;
  }

  if (known_sum != sum)
  {
    result++;
    fprintf(stderr, "Error in sum with integers: Result was %d instead of %d\n", sum, known_sum);
  }

  diff = (1000 * (1000 + 1)) / 2;
  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(-:diff)
  for (i = 1; i <= 1000; ++i)
