  for (int i = n; i < (n + ((chromo_length * 30) / 100)); i++)
  {
    z = i % chromo_length;
    Chro->genes[z] = p.genes[z];
  }

  int c = 0;
  int i = (z + 1) % chromo_length;
  while (i != z)
  {
    c = c % chromo_length;
    if (if_exist(Chro, m.genes[c]) != 1)
      Chro->genes[i] = m.genes[c];
    else
