void initialize_graph(graph *g)
{
  do
  {
    fprintf(stdout, "[debug] %s:%d:%s(): Initializing graph with payload\n", basename("/home/reemh/CLPP/github-clone-all/repos_final/amannougrahiya/imop-compiler/tests/imsuite/src/mis.c"), 27, __func__);
  }
  while (0);
  for (int i = 0; i < g->N; i++)
  {
    node *cur = elem_at(&g->vertices, i);
    payload *data = malloc(sizeof(payload));
    data->present = 1;
    data->in_mis = 0;
    data->r = 0;
    cur->data = data;
  }

}


void generate_random_field(graph *g)
{
  #pragma omp parallel for schedule(SCHEDULING_METHOD)
  for (int i = 0; i < g->N; i++)
  {
    node *cur = elem_at(&g->vertices, i);
    payload *data = cur->data;
    if (!data->present)
      continue;

    data->r = randnum();
  }

}


void decide_mis_entry(graph *g)
{
  #pragma omp parallel for schedule(SCHEDULING_METHOD)
  for (int i = 0; i < g->N; i++)
  {
    node *cur = elem_at(&g->vertices, i);
    payload *data = cur->data;
    if (!data->present)
      continue;

    int enter = 1;
    for (int i = 0; i < cur->degree; i++)
    {
      node *neighbor = *((node **) elem_at(&cur->neighbors, i));
      payload *neighbor_data = neighbor->data;
      if (data->r > neighbor_data->r)
      {
        enter = 0;
        break;
      }

    }

    if (enter)
    {
      data->present = 0;
      data->in_mis = 1;
    }

  }

}


void remove_mis_adjacent_nodes(graph *g)
{
  #pragma omp parallel for schedule(SCHEDULING_METHOD)
  for (int i = 0; i < g->N; i++)
  {
    node *cur = elem_at(&g->vertices, i);
    payload *data = cur->data;
    if (data->in_mis)
    {
      for (int i = 0; i < cur->degree; i++)
      {
        node *neighbor = *((node **) elem_at(&cur->neighbors, i));
        payload *neighbor_data = neighbor->data;
        neighbor_data->present = 0;
      }

    }

  }

}


int do_present_nodes_exist(graph *g)
{
  int keep_going = 0;
  #pragma omp parallel for schedule(SCHEDULING_METHOD)
  for (int i = 0; i < g->N; i++)
  {
    node *cur = elem_at(&g->vertices, i);
    payload *data = cur->data;
    if (data->present)
      keep_going = 1;

  }

  return keep_going;
}


