static void merge(int *a, int *b, int m, int n)
{
  int i = 0;
  int j = 0;
  int k = 0;
  int l = 0;
  int *c = (int *) malloc((m + n) * (sizeof(int)));
  while ((i < m) && (j < n))
  {
    if (a[i] <= b[j])
    {
      c[k] = a[i++];
    }
    else
    {
      c[k] = b[j++];
    }

    k++;
  }

  if (i < m)
  {
    for (l = i; l < m; l++, k++)
    {
      c[k] = a[l];
    }

  }
  else
  {
    for (l = j; l < n; l++, k++)
    {
      c[k] = b[l];
    }

  }

  for (i = 0; i < (m + n); i++)
  {
    a[i] = c[i];
  }

  free(c);
}

