void moveCity()
{
  register int index1;
  register int index2;
  float tempDist = totDist;
  do
  {
    index1 = 1 + (rand() % (10000 - 1));
    index2 = 1 + (rand() % (10000 - 1));
  }
  while (index1 == index2);
  register int point1 = route[index1];
  register int point2 = route[index2];
  if (abs(index1 - index2) == 1)
  {
    if (index1 > index2)
    {
      int tmp = index1;
      index1 = index2;
      index2 = tmp;
    }

    tempDist -= dist(route[index1], route[index1 - 1]);
    tempDist -= dist(route[index2], route[index2 + 1]);
    tempDist += dist(route[index1], route[index2 + 1]);
    tempDist += dist(route[index2], route[index1 - 1]);
  }
  else
  {
    tempDist -= dist(route[index1], route[index1 - 1]);
    tempDist -= dist(route[index1], route[index1 + 1]);
    tempDist -= dist(route[index2], route[index2 - 1]);
    tempDist -= dist(route[index2], route[index2 + 1]);
    tempDist += dist(route[index1], route[index2 - 1]);
    tempDist += dist(route[index1], route[index2 + 1]);
    tempDist += dist(route[index2], route[index1 - 1]);
    tempDist += dist(route[index2], route[index1 + 1]);
  }

  if (tempDist < totDist)
