Color mandelbrot(int px, int py, Color *palette)
{
  double x = 0;
  double y = 0;
  double x0 = (-2) + (px * ((1.5 - (-2)) / (7680 * 1.0)));
  double y0 = (-1.0) + (py * ((1.0 - (-1.0)) / (4320 * 1.0)));
  double i = 0;
  double x2 = 0;
  double y2 = 0;
  while (((x2 + y2) <= 20) && (i < 8000))
  {
    y = ((2 * x) * y) + y0;
    x = (x2 - y2) + x0;
    x2 = x * x;
    y2 = y * y;
    i++;
  }

  if (i < 8000)
  {
    double log_zn = log((x * x) + (y * y)) / 2.0;
    double nu = log(log_zn / log(2.0)) / log(2.0);
    i += 1.0 - nu;
  }

  Color c1 = palette[(int) i];
  Color c2;
  if ((((int) i) + 1) > 8000)
  {
    c2 = palette[(int) i];
  }
  else
  {
    c2 = palette[((int) i) + 1];
  }

  double mod = i - ((int) i);
  return (Color){.r = (int) lerp(c1.r, c2.r, mod), .g = (int) lerp(c1.g, c2.g, mod), .b = (int) lerp(c1.b, c2.b, mod)};
}

