{
  if (((!node->has_children) && node->has_particle) && (node->particle != particle))
  {
    double r = sqrt(((x[particle] - node->c_x) * (x[particle] - node->c_x)) + ((y[particle] - node->c_y) * (y[particle] - node->c_y)));
    calculate_force(particle, node, r);
  }
  else
