int determinant(int n, int **a)
{
  int d = 0;
  if (n == 1)
    return a[0][0];

  for (int i = 1; i <= n; i++)
  {
    int **b = makemat(n, a, i);
    if ((i % 2) == 0)
      d -= a[0][i - 1] * determinant(n - 1, b);
    else
      if ((i % 2) == 1)
      d += a[0][i - 1] * determinant(n - 1, b);


  }

  return d;
}


