void relax()
{
  #pragma omp parallel for shared(A,B) private(i,j)
  for (i = 1; i <= (N - 2); i++)
    for (j = 1; j <= (N - 2); j++)
  {
    B[i][j] = (((A[i - 1][j] + A[i + 1][j]) + A[i][j - 1]) + A[i][j + 1]) / 4.;
  }


}


void resid()
{
  #pragma omp parallel for private(i,j)
  for (i = 1; i <= (N - 2); i++)
  {
    double local_eps = eps;
    for (j = 1; j <= (N - 2); j++)
    {
      double e;
      e = fabs(A[i][j] - B[i][j]);
      A[i][j] = B[i][j];
      local_eps = (eps > e) ? (eps) : (e);
    }

    eps = (eps > local_eps) ? (eps) : (local_eps);
  }

}

