static void pbkdf2_sha1(const unsigned char *K, int KL, const unsigned char *S, int SL, int R, unsigned char *out, int outlen, int skip_bytes)
{
  union 
  {
    uint32_t x32[20 / (sizeof(uint32_t))];
    unsigned char out[20];
  } tmp;
  int loop;
  int loops;
  int i;
  int accum = 0;
  sph_sha1_context ipad;
  sph_sha1_context opad;
  _pbkdf2_sha1_load_hmac(K, KL, &ipad, &opad);
  loops = ((skip_bytes + outlen) + (20 - 1)) / 20;
  loop = (skip_bytes / 20) + 1;
  skip_bytes %= 20;
  while (loop <= loops)
  {
    _pbkdf2_sha1(S, SL, R, tmp.x32, loop, &ipad, &opad);
    for (i = skip_bytes; (i < 20) && (accum < outlen); i++)
    {
      out[accum++] = ((uint8_t *) tmp.out)[i];
    }

    loop++;
    skip_bytes = 0;
  }

}


static int kcdecrypt(unsigned char *key, unsigned char *iv, unsigned char *data)
{
  unsigned char out[48];
  DES_cblock key1;
  DES_cblock key2;
  DES_cblock key3;
  DES_cblock ivec;
  DES_key_schedule ks1;
  DES_key_schedule ks2;
  DES_key_schedule ks3;
  memset(out, 0, sizeof(out));
  memcpy(key1, key, 8);
  memcpy(key2, key + 8, 8);
  memcpy(key3, key + 16, 8);
  DES_set_key_unchecked((DES_cblock *) key1, &ks1);
  DES_set_key_unchecked((DES_cblock *) key2, &ks2);
  DES_set_key_unchecked((DES_cblock *) key3, &ks3);
  memcpy(ivec, iv, 8);
  DES_ede3_cbc_encrypt(data, out, 48, &ks1, &ks2, &ks3, &ivec, 0);
  if ((out[47] != 4) || (check_pkcs_pad(out, 48, 8) < 0))
    return -1;

  return 0;
}

