int run_convolution_layer4(unsigned char in_layer[], const float bias[], const float weight[], unsigned int detect[])
{
  int m;
  int n;
  int q;
  int r;
  int detections = 0;
  int posx;
  int posy;
  float y;
  int set = 0;
  float max;
  omp_set_num_threads(Parallelism);
  #pragma omp parallel for
  for (m = 0; m < 173; m++)
  {
    for (n = 0; n < 313; n++)
    {
      y = bias[0];
      for (q = 0; q < 80; q++)
      {
        y += in_layer[(((q * 173) * 313) + (m * 313)) + n] * weight[q];
      }

      if (y >= 0.0f)
      {
        max = 0;
        for (r = 1; r < 8; r++)
        {
          y = bias[r];
          for (q = 0; q < 80; q++)
          {
            y += in_layer[(((q * 173) * 313) + (m * 313)) + n] * weight[(r * 80) + q];
          }

          if ((y >= 0.0f) && (y > max))
          {
            max = y;
            posx = n * 4;
            posy = m * 4;
            detect[detections * 4] = posx;
            detect[(detections * 4) + 1] = posy;
            detect[(detections * 4) + 2] = r;
            detect[(detections * 4) + 3] = 100.0f / (1 + expf((-y) / 256));
            set = 1;
          }

        }

        if (set == 1)
        {
          detections = detections + 1;
          set = 0;
        }

      }

    }

  }

  return detections;
}

