void diagnal_intersection(int a[], int b[], long long int asize, long long int bsize, int threads, long long int *astart, long long int *bstart, long long int i, long long int diag)
{
  if (i == 0)
  {
    *astart = 0;
    *bstart = 0;
    return;
  }

  int overhalf_a = (diag > asize) ? (1) : (0);
  int overhalf_b = (diag > bsize) ? (1) : (0);
  long long int overhalf_offset_b = (overhalf_a == 0) ? (0) : (diag - asize);
  long long int overhalf_offset_a = (overhalf_b == 0) ? (0) : (diag - bsize);
  if (overhalf_a && overhalf_b)
  {
    diag = (bsize + asize) - diag;
  }
  else
    if (overhalf_a && (!overhalf_b))
  {
    diag = asize;
  }
  else
    if (overhalf_b && (!overhalf_a))
  {
    diag = bsize;
  }



  long long int left = 0;
  long long int right = diag;
  long long int ai = -1;
  long long int bi = -1;
  while (left <= right)
  {
    int mid = (left + right) / 2;
    ai = (diag - mid) + overhalf_offset_a;
    bi = mid + overhalf_offset_b;
    *astart = ai;
    *bstart = bi;
    if (((bi >= bsize) && (a[ai] > b[bi - 1])) || ((ai >= asize) && (a[ai - 1] < b[bi])))
      break;

    if ((a[ai] >= b[bi - 1]) && (a[ai - 1] < b[bi]))
      break;
    else
      if ((ai == asize) || (a[ai] >= b[bi - 1]))
      left = mid + 1;
    else
      right = mid - 1;


  }

  return;
}


void merge_serial_general(int a[], int b[], long long int astart, long long int bstart, int temp[], long long int tempstart, long long int size, long long int asize, long long int bsize, long long int *ainc, long long int *binc)
{
  long long int i1 = astart;
  long long int i2 = bstart;
  int tempi = 0;
  while (((tempi < size) && (i1 < asize)) && (i2 < bsize))
  {
    if (a[i1] < b[i2])
    {
      temp[tempi + tempstart] = a[i1];
      i1++;
    }
    else
    {
      temp[tempi + tempstart] = b[i2];
      i2++;
    }

    tempi++;
  }

  while ((tempi < size) && (i1 < asize))
  {
    temp[tempi + tempstart] = a[i1];
    i1++;
    tempi++;
  }

  while ((tempi < size) && (i2 < bsize))
  {
    temp[tempi + tempstart] = b[i2];
    i2++;
    tempi++;
  }

  if (ainc != 0)
    *ainc = i1;

  if (binc != 0)
    *binc = i2;

}

