static void com_dpc(int iside, int iel, int enumber, int n, int isize)
{
  int nn1start;
  int nn1end;
  int nn2start;
  int nn2end;
  int jstart;
  int jend;
  int istart;
  int iend;
  int i;
  int j;
  int nn1;
  int nn2;
  int imor = 0;
  double anc1;
  double ac;
  double anc2;
  double anc0;
  double temp = 0.0;
  if (enumber == 0)
  {
    nn1start = 1;
    nn1end = 1;
    nn2start = 1;
    nn2end = 2;
    jstart = 1;
    jend = 1;
    istart = 2;
    iend = 5 - 1;
  }
  else
    if (enumber == 1)
  {
    nn1start = 1;
    nn1end = 2;
    nn2start = 2;
    nn2end = 2;
    jstart = 2;
    jend = 5 - 1;
    istart = 5;
    iend = 5;
  }
  else
    if (enumber == 2)
  {
    nn1start = 2;
    nn1end = 2;
    nn2start = 1;
    nn2end = 2;
    jstart = 5;
    jend = 5;
    istart = 2;
    iend = 5 - 1;
  }
  else
    if (enumber == 3)
  {
    nn1start = 1;
    nn1end = 2;
    nn2start = 1;
    nn2end = 1;
    jstart = 2;
    jend = 5 - 1;
    istart = 1;
    iend = 1;
  }
  else
  {
    assert(0);
    nn1start = 0;
    nn1end = 0;
    nn2start = 0;
    nn2end = 0;
    jstart = 0;
    jend = 5 - 1;
    istart = 0;
    iend = 0;
  }




  if (n == 1)
  {
    anc1 = 2.0;
    ac = 1.0;
    anc0 = 1.0;
    anc2 = 0.0;
  }
  else
    if (n == 2)
  {
    anc1 = 2.0;
    ac = 2.0;
    anc0 = 0.0;
    anc2 = 0.0;
  }
  else
    if (n == 3)
  {
    anc2 = 2.0;
    ac = 2.0;
    anc1 = 0.0;
    anc0 = 0.0;
  }
  else
    if (n == 4)
  {
    anc1 = 0.0;
    ac = 3.0;
    anc2 = 1.0;
    anc0 = 0.0;
  }
  else
    if (n == 0)
  {
    anc1 = 1.0;
    ac = 1.0;
    anc2 = 0.0;
    anc0 = 0.0;
  }
  else
  {
    assert(0);
    anc1 = 0.0;
    ac = 0.0;
    anc2 = 0.0;
    anc0 = 0.0;
  }





  for (nn2 = nn2start - 1; nn2 < nn2end; nn2++)
