int test_omp_parallel_for_private()
{
  int sum;
  int i;
  int i2;
  int known_sum;
  sum = 0;
  i2 = 0;
  #pragma omp parallel for reduction(+:sum) schedule(static,1) private(i) private(i2)
  for (i = 1; i <= 1000; i++)
  {
    i2 = i;
    #pragma omp flush
    do_some_work();
    #pragma omp flush
    sum = sum + i2;
  }

  known_sum = (1000 * (1000 + 1)) / 2;
  return known_sum == sum;
}

