  }

  logic_or = 0;
  logics[1000 / 2] = 1;
  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(||:logic_or)
  for (i = 0; i < 1000; ++i)
  {
    logic_or = logic_or || logics[i];
  }

  if (!logic_or)
