    uint32_t v_comp = ((uint32_t) graph->sorted_edges_array->edges_array_dest[edge_idx_comp + mid]) & 0x3FFFFFFF;
    while (bottom < (top - 1))
    {
      if (u_iter < v_comp)
      {
        top = mid;
      }
      else
        if (u_iter > v_comp)
      {
        bottom = mid;
      }
      else
