float calcWeight(const char *str, const Weight *weights)
{
  int NumberOfStars = 0;
  int NumberOfColons = 0;
  int NumberOfPoints = 0;
  int NumberOfSpaces = 0;
  for (int i = 0; i < strlen(str); i++)
  {
    switch (str[i])
    {
      case '*':
        NumberOfStars++;
        break;

      case ':':
        NumberOfColons++;
        break;

      case '.':
        NumberOfPoints++;
        break;

      case ' ':
        NumberOfSpaces++;
        break;

      default:
        break;

    }

  }

  return (((weights->w1 * NumberOfStars) - (weights->w2 * NumberOfColons)) - (weights->w3 * NumberOfPoints)) - (weights->w4 * NumberOfSpaces);
}

