  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(^:exclusiv_bit_or)
  for (i = 0; i < 1000; ++i)
  {
    exclusiv_bit_or = exclusiv_bit_or ^ logics[i];
  }

  if (!exclusiv_bit_or)
  {
    result++;
