      arr[k++] = a[x++];
    }
    else
    {
      arr[k++] = a[y++];
    }

  }

  if (x <= mid)
  {
    while (x <= mid)
    {
      arr[k++] = a[x++];
    }

  }

  if (y <= j)
  {
    while (y <= j)
    {
      arr[k++] = a[y++];
    }

  }

  for (k = i; k <= j; k++)
  {
