int calculateDeterminant(size_t n, int matrix[][n])
{
  float ratio;
  int i;
  int j;
  int k;
  for (i = 0; i < n; i++)
  {
    for (j = 0; j < n; j++)
    {
      if (j > i)
      {
        ratio = matrix[j][i] / matrix[i][i];
        for (k = 0; k < n; k++)
        {
          matrix[j][k] -= ratio * matrix[i][k];
        }

      }

    }

  }

  int determinant = 1;
  for (i = 0; i < n; i++)
  {
    determinant *= matrix[i][i];
  }

  return determinant;
}

