        }

      }

    }

  }

}


unsigned int sendrecv_boundary_cells(MPI_Comm comm, cell_t **sendbuf, const unsigned int *sendcount, cell_t **received)
{
  int rank;
  int my_coords[3];
  MPI_Comm_rank(comm, &rank);
  MPI_Cart_coords(comm, rank, 3, my_coords);
  int shift = 0;
  int direction[3];
  cell_t *recvbufs[26];
  unsigned int recvcount[26];
  for (direction[0] = -1; direction[0] < 2; direction[0]++)
  {
    for (direction[1] = -1; direction[1] < 2; direction[1]++)
    {
      for (direction[2] = -1; direction[2] < 2; direction[2]++)
      {
        if (!((direction[0] || direction[1]) || direction[2]))
        {
          continue;
        }

        int src_coords[3] = {my_coords[0] - direction[0], my_coords[1] - direction[1], my_coords[2] - direction[2]};
        int dest_coords[3] = {my_coords[0] + direction[0], my_coords[1] + direction[1], my_coords[2] + direction[2]};
        int source;
        int dest;
        MPI_Cart_rank(comm, src_coords, &source);
        MPI_Cart_rank(comm, dest_coords, &dest);
        if ((source == rank) && (dest == rank))
        {
          recvbufs[shift] = malloc(0);
          recvcount[shift] = 0;
          shift++;
          continue;
        }

        MPI_Sendrecv(&sendcount[shift], 1, (MPI_Datatype) 0x4c000406, dest, 18361, &recvcount[shift], 1, (MPI_Datatype) 0x4c000406, source, 18361, comm, 0);
        recvbufs[shift] = calloc((size_t) recvcount[shift], sizeof(cell_t));
        MPI_Sendrecv(sendbuf[shift], sendcount[shift], (MPI_Datatype) 0x4c000819, dest, 25341, recvbufs[shift], recvcount[shift], (MPI_Datatype) 0x4c000819, source, 25341, comm, 0);
        shift++;
      }

    }

  }

  unsigned int total_cells_received = 0;
  for (int i = 0; i < 26; i++)
  {
    total_cells_received += recvcount[i];
  }

  *received = (cell_t *) calloc(total_cells_received, sizeof(cell_t));
  int copied_so_far = 0;
  for (int i = 0; i < 26; i++)
  {
    for (int j = 0; j < recvcount[i]; j++)
    {
      (*received)[copied_so_far++] = recvbufs[i][j];
    }

    free(recvbufs[i]);
  }

  return total_cells_received;
}


static unsigned int get_cells_in_region(const hashtable_t *ht, cell_t lower_bound, cell_t upper_bound, unsigned int size, int overlap, cell_t *out)
{
  unsigned int num_cells = 0;
  cell_t c;
  for (unsigned int i = 0; i < ht->capacity; i++)
  {
    c = ht->table[i];
    if (c == 0)
      continue;

    if (in_region(c, lower_bound, upper_bound, size, overlap))
      out[num_cells++] = c;

  }

  return num_cells;
}

