void fix_stage(int n, int lp, int q, int t, float s1[q], int s2[q], float dp1[q][t], int Y[t], float A[q][q], float B[q][n])
{
  for (int i = 0; i < q; i++)
  {
    float max = -INFINITY;
    int arg_max = -1;
    double curr_log_prob;
    for (int j = 0; j < q; j++)
    {
      curr_log_prob = (dp1[j][lp - 1] + A[j][i]) + B[i][Y[lp]];
      if (curr_log_prob > max)
      {
        max = curr_log_prob;
        arg_max = j;
      }

    }

    s1[i] = max;
    s2[i] = arg_max;
  }

}


