        nearest_city.dist = dist;
        nearest_city.city = i;
      }

    }

  }

  Sequence[to_visit] = nearest_city.city;
  Visited[nearest_city.city] = 1;
  return nearest_city.dist;
}


float find_second_nearest(int to_visit)
{
  float min_dist1 = 1e6;
  float min_dist2;
