  int nearest_city1;
  int nearest_city2;
  for (int i = 1; i < 10000; i++)
  {
    if (!Visited[i])
    {
      dist = distance(i, Sequence[to_visit - 1]);
      if (dist <= min_dist1)
      {
        min_dist2 = min_dist1;
        nearest_city2 = nearest_city1;
        min_dist1 = dist;
        nearest_city1 = i;
      }
      else
        if (dist <= min_dist2)
      {
        min_dist2 = dist;
        nearest_city2 = i;
      }


    }

  }

  if (to_visit == (10000 - 1))
  {
    Sequence[to_visit] = nearest_city1;
    Visited[nearest_city1] = 1;
    return min_dist1;
  }
  else
  {
    Sequence[to_visit] = nearest_city2;
    Visited[nearest_city2] = 1;
    return min_dist2;
  }

}

