      if (number <= (aux + 0.0001))
      {
        city = j;
        condicion = 1;
      }

    }

    j++;
  }

  if (city == (-1))
  {
    printf("NO asigno");
    printf("\n %.8lf - %.8lf iter=%i", aux, number, j - 1);
    exit(-1);
  }

  return city;
}

