uint32_t bellmanFordAtomicMin(uint32_t *dist, uint32_t newValue)
{
  uint32_t oldValue;
  uint32_t flag = 0;
  do
  {
    oldValue = *dist;
    if (oldValue > newValue)
    {
      if (__sync_bool_compare_and_swap(dist, oldValue, newValue))
      {
        flag = 1;
      }

    }
    else
    {
      return 0;
    }

  }
  while (!flag);
  return 1;
}

