void radiance(const double *ray_origin, const double *ray_direction, int depth, unsigned int *PRNG_state, double *out)
{
  int id = 0;
  double t;
  if (!intersect(ray_origin, ray_direction, &t, &id))
  {
    zero(out);
    return;
  }

  const struct Sphere *obj = &spheres[id];
  double x[3];
  copy(ray_origin, x);
  axpy(t, ray_direction, x);
  double n[3];
  copy(x, n);
  axpy(-1, obj->position, n);
  normalize(n);
  double nl[3];
  copy(n, nl);
  if (dot(n, ray_direction) > 0)
    scal(-1, nl);

  double f[3];
  copy(obj->color, f);
  double p = obj->max_reflexivity;
  depth++;
  if (depth > KILL_DEPTH)
  {
    if ((((double) rand_r(PRNG_state)) / 32767) < p)
    {
      scal(1 / p, f);
    }
    else
    {
      copy(obj->emission, out);
      return;
    }

  }

  if (obj->refl == DIFF)
  {
    double r1 = ((2 * M_PI) * ((double) rand_r(PRNG_state))) / 32767;
    double r2 = ((double) rand_r(PRNG_state)) / 32767;
    double r2s = sqrt(r2);
    double w[3];
    copy(nl, w);
    double u[3];
    double uw[3] = {0, 0, 0};
    if (fabs(w[0]) > .1)
      uw[1] = 1;
    else
      uw[0] = 1;

    cross(uw, w, u);
    normalize(u);
    double v[3];
    cross(w, u, v);
    double d[3];
    zero(d);
    axpy(cos(r1) * r2s, u, d);
    axpy(sin(r1) * r2s, v, d);
    axpy(sqrt(1 - r2), w, d);
    normalize(d);
    double rec[3];
    radiance(x, d, depth, PRNG_state, rec);
    mul(f, rec, out);
    axpy(1, obj->emission, out);
    return;
  }

  double reflected_dir[3];
  copy(ray_direction, reflected_dir);
  axpy((-2) * dot(n, ray_direction), n, reflected_dir);
  if (obj->refl == SPEC)
  {
    double rec[3];
    radiance(x, reflected_dir, depth, PRNG_state, rec);
    mul(f, rec, out);
    axpy(1, obj->emission, out);
    return;
  }

  bool into = dot(n, nl) > 0;
  double nc = 1;
  double nt = 1.5;
  double nnt = (into) ? (nc / nt) : (nt / nc);
  double ddn = dot(ray_direction, nl);
  double cos2t = 1 - ((nnt * nnt) * (1 - (ddn * ddn)));
  if (cos2t < 0)
  {
    double rec[3];
    radiance(x, reflected_dir, depth, PRNG_state, rec);
    mul(f, rec, out);
    axpy(1, obj->emission, out);
    return;
  }

  double tdir[3];
  zero(tdir);
  axpy(nnt, ray_direction, tdir);
  axpy((-((into) ? (1) : (-1))) * ((ddn * nnt) + sqrt(cos2t)), n, tdir);
  double a = nt - nc;
  double b = nt + nc;
  double R0 = (a * a) / (b * b);
  double c = 1 - ((into) ? (-ddn) : (dot(tdir, n)));
  double Re = R0 + ((((((1 - R0) * c) * c) * c) * c) * c);
  double Tr = 1 - Re;
  double rec[3];
  if (depth > SPLIT_DEPTH)
  {
    double P = .25 + (.5 * Re);
    if ((((double) rand_r(PRNG_state)) / 32767) < P)
    {
      radiance(x, reflected_dir, depth, PRNG_state, rec);
      double RP = Re / P;
      scal(RP, rec);
    }
    else
    {
      radiance(x, tdir, depth, PRNG_state, rec);
      double TP = Tr / (1 - P);
      scal(TP, rec);
    }

  }
  else
  {
    double rec_re[3];
    double rec_tr[3];
    radiance(x, reflected_dir, depth, PRNG_state, rec_re);
    radiance(x, tdir, depth, PRNG_state, rec_tr);
    zero(rec);
    axpy(Re, rec_re, rec);
    axpy(Tr, rec_tr, rec);
  }

  mul(f, rec, out);
  axpy(1, obj->emission, out);
  return;
}


