int binary_search_right_boundary_kernel(const int *row_pointer, const int key_input, const int size)
{
  int start = 0;
  int stop = size - 1;
  int median;
  int key_median;
  while (stop >= start)
  {
    median = (stop + start) / 2;
    key_median = row_pointer[median];
    if (key_input >= key_median)
      start = median + 1;
    else
      stop = median - 1;

  }

  return start;
}

