void changeValue(nodeIntMap *map, node_t key, int inc)
{
  int i;
  for (i = 0; i < map->size; i++)
  {
    if (key == map->list[i].key)
    {
      map->list[i].value += inc;
      break;
    }

  }

  if (i == map->size)
  {
    map->list[i].key = key;
    map->list[i].value = inc;
    map->size++;
  }

}


node_t mapMaxValueKey(nodeIntMap *map)
{
  int max = 0;
