static int ConvertFromHex(unsigned char *p, int len)
{
  unsigned char *cp;
  unsigned int i;
  unsigned int x;
  if ((!p) || memcmp(p, "HEX$", 4))
    return len;

  len -= 4;
  len >>= 1;
  cp = p;
  x = len;
  for (i = 4; x; --x, i += 2)
  {
    *(cp++) = (atoi16[ARCH_INDEX(p[i])] * 16) + atoi16[ARCH_INDEX(p[i + 1])];
  }

  *cp = 0;
  return len;
}


