void TSPRec(int **adj, int curr_bound, int curr_weight, int level, int curr_pat[], int vis[])
{
  if (level == N)
  {
    if (adj[curr_pat[level - 1]][curr_pat[0]] != 0)
    {
      int curr_res = curr_weight + adj[curr_pat[level - 1]][curr_pat[0]];
      #pragma omp critical
      if (curr_res < final_res)
      {
        copyToFinal(curr_pat);
        final_res = curr_res;
      }

    }

    return;
  }

  int i;
  #pragma omp parallel for default(none) firstprivate(curr_bound, curr_weight, level) shared(curr_pat, vis,adj,final_res,N)
  for (i = 0; i < N; i++)
  {
    int visited[N];
    int curr_path[N];
    int j;
    for (j = 0; j < N; j++)
    {
      visited[j] = vis[j];
    }

    for (j = 0; j < N; j++)
      curr_path[j] = curr_pat[j];

    if ((adj[curr_path[level - 1]][i] != 0) && (visited[i] == 0))
    {
      int temp = curr_bound;
      curr_weight += adj[curr_path[level - 1]][i];
      if (level == 1)
        curr_bound -= (firstMin(adj, curr_path[level - 1]) + firstMin(adj, i)) / 2;
      else
        curr_bound -= (secondMin(adj, curr_path[level - 1]) + firstMin(adj, i)) / 2;

      if ((curr_bound + curr_weight) < final_res)
      {
        curr_path[level] = i;
        visited[i] = 1;
