uint64_t *findFactors(uint64_t semiprime)
{
  bool factorsFound = 0;
  uint64_t *factors = malloc((sizeof(uint64_t)) * 2);
  uint64_t factorOne;
  uint64_t factorTwo;
  uint64_t arraySize;
  factorOne = 0;
  factorTwo = 0;
  arraySize = (sizeof(primesTable)) / (sizeof(int));
  for (int i = 0; (i < arraySize) && (!factorsFound); i++)
  {
    factorOne = primesTable[i];
    #pragma omp parallel for shared(factorsFound)
    for (int j = 0; j < arraySize; j++)
    {
      factorTwo = primesTable[j];
      if ((factorOne * factorTwo) == semiprime)
      {
        #pragma omp critical
        {
          factors[0] = factorOne;
          factors[1] = factorTwo;
          factorsFound = 1;
        }
        #pragma omp cancel for
      }

    }

  }

  if (!factorsFound)
  {
    factors[0] = 0;
    factors[1] = 0;
  }

  return factors;
}


