static int queue_pop(queue *q, pthread_mutex_t *mutex)
{
  int ret;
  elem *temp;
  pthread_mutex_lock(mutex);
  ret = q->head->v;
  temp = q->head;
  q->head = q->head->next;
  free(temp);
  q->size--;
  pthread_mutex_unlock(mutex);
  return ret;
}

