    if (i < j)
    {
      ctmp = r[i];
      r[i] = r[j];
      r[j] = ctmp;
    }

    ;
    k = i2;
    while (k <= j)
    {
      j -= k;
      k >>= 1;
    }

    j += k;
  }

  for (i = n, m = 0; i > 1; m++, i /= 2)
    ;

