void inflow_check(struct GridGeom *G, struct FluidState *S, int i, int j, int k, int type)
{
  double alpha;
  double beta1;
  double vsq;
  ucon_calc(G, S, i, j, k, 3);
  if (((S->ucon[1][k][j][i] > 0.) && (type == 0)) || ((S->ucon[1][k][j][i] < 0.) && (type == 1)))
  {
    double gamma = mhd_gamma_calc(G, S, i, j, k, 3);
    S->P[2][k][j][i] /= gamma;
    S->P[3][k][j][i] /= gamma;
    S->P[4][k][j][i] /= gamma;
    alpha = G->lapse[3][j][i];
    beta1 = (G->gcon[3][0][1][j][i] * alpha) * alpha;
    S->P[2][k][j][i] = beta1 / alpha;
    vsq = 0.;
    for (int mu = 1; mu < 4; mu++)
    {
      for (int nu = 1; nu < 4; nu++)
      {
        vsq += (G->gcov[3][mu][nu][j][i] * S->P[(2 + mu) - 1][k][j][i]) * S->P[(2 + nu) - 1][k][j][i];
      }

    }

    if (fabs(vsq) < 1.e-13)
      vsq = 1.e-13;

    if (vsq >= 1.)
    {
      vsq = 1. - (1. / (50. * 50.));
    }

    gamma = 1. / sqrt(1. - vsq);
    S->P[2][k][j][i] *= gamma;
    S->P[3][k][j][i] *= gamma;
    S->P[4][k][j][i] *= gamma;
  }

}

