int hooke(int nvars, double startpt[250], double endpt[250], double rho, double epsilon, int itermax)
{
  double delta[250];
  double newf;
  double fbefore;
  double steplength;
  double tmp;
  double xbefore[250];
  double newx[250];
  int i;
  int j;
  int keep;
  int iters;
  int iadj;
  for (i = 0; i < nvars; i++)
  {
    newx[i] = (xbefore[i] = startpt[i]);
    delta[i] = fabs(startpt[i] * rho);
    if (delta[i] == 0.0)
      delta[i] = rho;

  }

  iadj = 0;
  steplength = rho;
  iters = 0;
  fbefore = f(newx, nvars);
  newf = fbefore;
  while ((iters < itermax) && (steplength > epsilon))
  {
    iters++;
    iadj++;
    for (i = 0; i < nvars; i++)
    {
      newx[i] = xbefore[i];
    }

    newf = best_nearby(delta, newx, fbefore, nvars);
    keep = 1;
    while ((newf < fbefore) && (keep == 1))
    {
      iadj = 0;
      for (i = 0; i < nvars; i++)
      {
        if (newx[i] <= xbefore[i])
          delta[i] = 0.0 - fabs(delta[i]);
        else
          delta[i] = fabs(delta[i]);

        tmp = xbefore[i];
        xbefore[i] = newx[i];
        newx[i] = (newx[i] + newx[i]) - tmp;
      }

      fbefore = newf;
      newf = best_nearby(delta, newx, fbefore, nvars);
      if (newf >= fbefore)
        break;

      keep = 0;
      for (i = 0; i < nvars; i++)
      {
        keep = 1;
        if (fabs(newx[i] - xbefore[i]) > (0.5 * fabs(delta[i])))
          break;
        else
          keep = 0;

      }

    }

    if ((steplength >= epsilon) && (newf >= fbefore))
    {
      steplength = steplength * rho;
      for (i = 0; i < nvars; i++)
      {
        delta[i] *= rho;
      }

    }

  }

  for (i = 0; i < nvars; i++)
    endpt[i] = xbefore[i];

  return iters;
}


