inline void mhd_calc(struct FluidState *S, int i, int j, int k, int dir, double *mhd)
{
  double u;
  double pres;
  double w;
  double bsq;
  double eta;
  double ptot;
  u = S->P[1][k][j][i];
  pres = (gam - 1.) * u;
  w = (pres + S->P[0][k][j][i]) + u;
  bsq = bsq_calc(S, i, j, k);
  eta = w + bsq;
  ptot = pres + (0.5 * bsq);
  for (int mu = 0; mu < 4; mu++)
  {
    mhd[mu] = (((eta * S->ucon[dir][k][j][i]) * S->ucov[mu][k][j][i]) + (ptot * ((dir == mu) ? (1.) : (0.)))) - (S->bcon[dir][k][j][i] * S->bcov[mu][k][j][i]);
  }

}

