inline static void CalcForces()
{
  utot = 0.0;
  if (1 == 0)
  {
    for (int i = 1; i < N; ++i)
    {
      for (int j = 0; j < i; ++j)
      {
        double r2 = 0.0;
        double rij[3];
        for (int k = 0; k < 3; ++k)
        {
          rij[k] = rn[i][k] - rn[j][k];
          if (rij[k] > L2[k])
          {
            rij[k] -= L[k];
          }
          else
            if (rij[k] < (-L2[k]))
          {
            rij[k] += L[k];
          }


          r2 += rij[k] * rij[k];
        }

        double f_r = 0;
        utot += Potential(r2);
        f_r = ForceDevByRange(r2);
        assert((r2 != INFINITY) && (r2 != 0));
        for (int k = 0; k < 3; ++k)
        {
          assert(f_r == f_r);
          f[i][k] += ((float) f_r) * ((float) rij[k]);
          f[j][k] -= ((float) f_r) * ((float) rij[k]);
        }

      }

    }

  }
  else
  {
    #pragma omp parallel for reduction(+: utot) num_threads(4)
    for (int i = 0; i < N; ++i)
    {
      for (int j = 0; j < N; ++j)
      {
        if (i != j)
        {
          double r2 = 0.0;
          double rij[3];
          for (int k = 0; k < 3; ++k)
          {
            rij[k] = rn[i][k] - rn[j][k];
            if (rij[k] > L2[k])
            {
              rij[k] -= L[k];
            }
            else
              if (rij[k] < (-L2[k]))
            {
              rij[k] += L[k];
            }


            r2 += rij[k] * rij[k];
          }

          utot += Potential(r2);
          double f_r = ForceDevByRange(r2);
          assert((r2 != INFINITY) && (r2 != 0));
          for (int k = 0; k < 3; ++k)
          {
            assert(f_r == f_r);
            f[i][k] += ((float) f_r) * ((float) rij[k]);
          }

        }

      }

    }

    utot /= 2.0;
  }

}


