      v[i][k] += (((float) f[i][k]) * ((float) dt)) / ((float) m[i]);
      r[i][k] += ((float) v[i][k]) * ((float) dt);
      assert(r[i][k] == r[i][k]);
    }

  }

}


inline static void CalcEnergy()
{
  K = 0;
  for (int i = 0; i < N; ++i)
  {
    double v2 = 0;
    for (int k = 0; k < 3; ++k)
    {
      v2 += ((float) v[i][k]) * ((float) v[i][k]);
    }

    K += ((float) m[i]) * (((float) v2) / 2.0);
    assert(K != INFINITY);
  }

}


inline static void CalcTemp()
{
  Temp = 2.0 * ((K / N) / 3.0);
}


inline static void Thermostat(int cur_iter)
{
  if (1)
