static void vtp_secret_derive(char *password, int length, unsigned char *output)
{
  MD5_CTX ctx;
  unsigned char *cp;
  unsigned char buf[55][64];
  int bufs_used = 0;
  int local_cnt = 0;
  int i;
  int j;
  if (length == 0)
  {
    memset(output, 0, 16);
    return;
  }

  cp = buf[bufs_used];
  for (;;)
  {
    if ((local_cnt + length) <= 64)
    {
      memcpy(&cp[local_cnt], password, length);
      local_cnt += length;
      if (local_cnt == 64)
      {
        bufs_used++;
        break;
      }

    }
    else
    {
      int spill = (local_cnt + length) - 64;
      memcpy(&cp[local_cnt], password, length - spill);
      cp = buf[++bufs_used];
      memcpy(cp, &password[length - spill], spill);
      local_cnt = spill;
    }

  }

  john_MD5_Init(&ctx);
  for (i = 0, j = 0; i < 1563; ++i)
  {
    john_MD5_Update(&ctx, buf[j++], 64);
    if (j == bufs_used)
      j = 0;

  }

  john_MD5_Final(output, &ctx);
}

