      break;

    case 1:
      return sqrt(pow(p1_x - p2_x, 2) + pow(p1_y - p2_y, 2));
      break;

    case 2:
      return pow(p1_x - p2_x, 2) + pow(p1_y - p2_y, 2);
      break;

    default:
      return 0;
      break;

  }

}

