RSComplex c_div(RSComplex A, RSComplex B)
{
  double a = A.r;
  double b = A.i;
  double c = B.r;
  double d = B.i;
  RSComplex C;
  double denom = (c * c) + (d * d);
  C.r = ((a * c) + (b * d)) / denom;
  C.i = ((b * c) - (a * d)) / denom;
  return C;
}


RSComplex c_sub(RSComplex A, RSComplex B)
{
  RSComplex C;
  C.r = A.r - B.r;
  C.i = A.i - B.i;
