inline int IterateMandelbrotOMPOPT(int a, int b)
{
  int x;
  int y;
  int x2;
  int y2;
  int m2;
  int co;
  int ite;
  unsigned int i;
  const int one = _mm_set1_ps(1.0f);
  const int th = _mm_set1_ps(4.0f);
  x = _mm_setzero_ps();
  y = _mm_setzero_ps();
  x2 = _mm_setzero_ps();
  y2 = _mm_setzero_ps();
  co = _mm_setzero_ps();
  ite = _mm_setzero_ps();
  for (i = 0; i < 2048; i++)
  {
    y = _mm_mul_ps(x, y);
    y = _mm_add_ps(_mm_add_ps(y, y), b);
    x = _mm_add_ps(_mm_sub_ps(x2, y2), a);
    x2 = _mm_mul_ps(x, x);
    y2 = _mm_mul_ps(y, y);
    m2 = _mm_add_ps(x2, y2);
    co = _mm_or_ps(co, _mm_cmpgt_ps(m2, th));
    ite = _mm_add_ps(ite, _mm_andnot_ps(co, one));
    if (_mm_movemask_ps(co) == 0x0f)
      break;

  }

  const int bb = _mm_cvtps_epi32(ite);
  const int gg = _mm_slli_si128(bb, 1);
  const int rr = _mm_slli_si128(bb, 2);
  const int color = _mm_or_si128(_mm_or_si128(rr, gg), bb);
  return color;
}

