    if ((a[ai] >= b[bi - 1]) && (a[ai - 1] < b[bi]))
      break;
    else
      if ((ai == asize) || (a[ai] >= b[bi - 1]))
      left = mid + 1;
    else
      right = mid - 1;


  }

  return;
}


