int test_omp_parallel_reduction()
{
  int sum;
  int known_sum;
  double dsum;
  double dknown_sum;
  double dt = 0.5;
  double rounding_error = 1.E-9;
  int diff;
  double ddiff;
  int product;
  int known_product;
  int logic_and;
  int logic_or;
  int bit_and;
  int bit_or;
  int exclusiv_bit_or;
  int logics[1000];
  int i;
  double dpt;
  int result;
  sum = 0;
  dsum = 0;
  product = 1;
  logic_and = 1;
  logic_or = 0;
  bit_and = 1;
  bit_or = 0;
  exclusiv_bit_or = 0;
  result = 0;
  dt = 1. / 3.;
  known_sum = (1000 * (1000 + 1)) / 2;
  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(+:sum)
  for (i = 1; i <= 1000; i++)
  {
    sum = sum + i;
  }

  if (known_sum != sum)
  {
    result++;
    fprintf(stderr, "Error in sum with integers: Result was %d instead of %d\n", sum, known_sum);
  }

  diff = (1000 * (1000 + 1)) / 2;
  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(-:diff)
  for (i = 1; i <= 1000; ++i)
  {
    diff = diff - i;
  }

  if (diff != 0)
  {
    result++;
    fprintf(stderr, "Error in difference with integers: Result was %d instead of 0.\n", diff);
  }

  dsum = 0;
  dpt = 1;
  for (i = 0; i < 20; ++i)
  {
    dpt *= dt;
  }

  dknown_sum = (1 - dpt) / (1 - dt);
  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(+:dsum)
  for (i = 0; i < 20; ++i)
  {
    dsum += pow(dt, i);
  }

  if (fabs(dsum - dknown_sum) > rounding_error)
  {
    result++;
    fprintf(stderr, "Error in sum with doubles: Result was %f instead of %f (Difference: %E)\n", dsum, dknown_sum, dsum - dknown_sum);
  }

  dpt = 1;
  for (i = 0; i < 20; ++i)
  {
    dpt *= dt;
  }

  fprintf(stderr, "\n");
  ddiff = (1 - dpt) / (1 - dt);
  #pragma omp parallel for schedule(dynamic,1) private(i) reduction(-:ddiff)
  for (i = 0; i < 20; ++i)
  {
    ddiff -= pow(dt, i);
  }

  if (fabs(ddiff) > rounding_error)
  {
