            total += imageArray[(curRow * w) + curCol];
            count += 1;
          }

        }

      }

      outImageArray[(row * w) + col] = total / count;
    }

  }

  t = clock() - t;
  double time_taken = ((double) t) / CLOCKS_PER_SEC;
