void scale(float *myCols, float *pivotCol, int dimension, int psize, int line, int OPENMP)
{
  int i;
  int j;
  #pragma omp parallel for private(i, j) if(OPENMP)
  for (i = 0; i < psize; i++)
  {
    for (j = 0; j < dimension; j++)
