void accelerate_life(const char *tick, char *tock, const int nx, const int ny)
{
  unsigned int idx;
  unsigned int x_l;
  unsigned int x_r;
  unsigned int y_u;
  unsigned int y_d;
  unsigned int j;
  #pragma omp parallel for private(j, idx, x_l, x_r, y_u, y_d)
  for (unsigned int i = 0; i < ny; i++)
  {
    for (j = 0; j < nx; j++)
    {
      idx = (i * nx) + j;
      x_r = (j + 1) % nx;
      x_l = (j == 0) ? (nx - 1) : (j - 1);
      y_u = (i + 1) % ny;
      y_d = (i == 0) ? (ny - 1) : (i - 1);
      int neighbours = 0;
      if (tick[(i * nx) + x_l] == 1)
        neighbours++;

      if (tick[(y_u * nx) + x_l] == 1)
        neighbours++;

      if (tick[(y_d * nx) + x_l] == 1)
        neighbours++;

      if (tick[(i * nx) + x_r] == 1)
        neighbours++;

      if (tick[(y_u * nx) + x_r] == 1)
        neighbours++;

      if (tick[(y_d * nx) + x_r] == 1)
        neighbours++;

      if (tick[(y_u * nx) + j] == 1)
        neighbours++;

      if (tick[(y_d * nx) + j] == 1)
        neighbours++;

      if (tick[idx] == 1)
      {
        if ((neighbours == 2) || (neighbours == 3))
          tock[idx] = 1;
        else
          tock[idx] = 0;

      }
      else
      {
        if (neighbours == 3)
          tock[idx] = 1;
        else
          tock[idx] = 0;

      }

    }

  }

}

