int *merge(int *A, int asize, int *B, int bsize, int *C)
{
  int ai;
  int bi;
  int ci;
  int i;
  int csize = asize + bsize;
  ai = 0;
  bi = 0;
  ci = 0;
  if (C == 0)
    C = (int *) malloc(csize * (sizeof(int)));

  while ((ai < asize) && (bi < bsize))
  {
    if (A[ai] <= B[bi])
    {
      C[ci] = A[ai];
      ci++;
      ai++;
    }
    else
    {
      C[ci] = B[bi];
      ci++;
      bi++;
    }

  }

  if (ai >= asize)
    for (i = ci; i < csize; i++, bi++)
    C[i] = B[bi];

  else
    if (bi >= bsize)
    for (i = ci; i < csize; i++, ai++)
    C[i] = A[ai];



  for (i = 0; i < asize; i++)
    A[i] = C[i];

  for (i = 0; i < bsize; i++)
    B[i] = C[asize + i];

  return C;
}

