int mandelbrot(int iter_max, double p_r, double p_i)
{
  int i;
  double z_r;
  double z_i;
  double work;
  z_r = p_r;
  z_i = p_i;
  work = (2.0 * z_r) * z_i;
  for (i = 1; (i < iter_max) && (((z_r *= z_r) + (z_i *= z_i)) < 4.0); i++)
  {
    z_r += p_r - z_i;
    z_i = p_i + work;
    work = (2.0 * z_r) * z_i;
  }

  return i;
}

