    printf("ERROR\tPlug #%d doesn't have any measurement\n", my_plug->id);
    exit(0);
  }

  for (i = 0; i < measurement_num; i++)
  {
    if (meas->next == 0)
    {
      printf("ERROR\tStill not exist Measurement #%d\n", meas->date);
      exit(0);
    }

    meas = meas->next;
  }

  return meas;
}

