static int decrypt(char *password)
{
  unsigned char out[16];
  AES_KEY akey;
  unsigned char iv[16];
  unsigned char biv[16];
  unsigned char key[32];
  int nrounds = 1;
  switch (cur_salt->cipher)
  {
    case 0:
      switch (cur_salt->md)
    {
      case 0:
        BytesToKey(256, md5, cur_salt->salt, (unsigned char *) password, strlen(password), nrounds, key, iv);
        JTR_AES_set_decrypt_key(key, 256, &akey);
        break;

      case 1:
        BytesToKey(256, sha1, cur_salt->salt, (unsigned char *) password, strlen(password), nrounds, key, iv);
        JTR_AES_set_decrypt_key(key, 256, &akey);
        break;

      case 2:
        BytesToKey(256, sha256, cur_salt->salt, (unsigned char *) password, strlen(password), nrounds, key, iv);
        JTR_AES_set_decrypt_key(key, 256, &akey);
        break;

    }

      break;

    case 1:
      switch (cur_salt->md)
    {
      case 0:
        BytesToKey(128, md5, cur_salt->salt, (unsigned char *) password, strlen(password), nrounds, key, iv);
        JTR_AES_set_decrypt_key(key, 128, &akey);
        break;

      case 1:
        BytesToKey(128, sha1, cur_salt->salt, (unsigned char *) password, strlen(password), nrounds, key, iv);
        JTR_AES_set_decrypt_key(key, 128, &akey);
        break;

      case 2:
        BytesToKey(128, sha256, cur_salt->salt, (unsigned char *) password, strlen(password), nrounds, key, iv);
        JTR_AES_set_decrypt_key(key, 128, &akey);
        break;

    }

      break;

  }

  memcpy(biv, iv, 16);
  if (cur_salt->inlined)
    JTR_AES_cbc_encrypt(cur_salt->last_chunks, out, 16, &akey, iv, 0);
  else
  {
    memcpy(iv, cur_salt->last_chunks, 16);
    JTR_AES_cbc_encrypt(cur_salt->last_chunks + 16, out, 16, &akey, iv, 0);
  }

  if (check_pkcs_pad(out, 16, 16) < 0)
    return -1;

  if (cur_salt->kpa)
    return kpa(key, biv, cur_salt->inlined);

  return 0;
}

