static void snmp_usm_password_to_key_md5(const uint8_t *password, uint32_t passwordlen, const uint8_t *engineID, uint32_t engineLength, uint8_t *key)
{
  uint8_t *cp;
  uint8_t password_buf[64];
  uint32_t password_index = 0;
  uint32_t count = 0;
  uint32_t i;
  MD5_CTX ctx;
  john_MD5_Init(&ctx);
  while (count < 1048576)
  {
    cp = password_buf;
    if (passwordlen != 0)
    {
      for (i = 0; i < 64; i++)
      {
        *(cp++) = password[password_index++];
        if (password_index >= passwordlen)
          password_index = 0;

      }

    }
    else
    {
      *cp = 0;
    }

    john_MD5_Update(&ctx, password_buf, 64);
    count += 64;
  }

  john_MD5_Final(key, &ctx);
  memcpy(password_buf, key, 16);
  memcpy(password_buf + 16, engineID, engineLength);
  memcpy((password_buf + 16) + engineLength, key, 16);
  john_MD5_Init(&ctx);
  john_MD5_Update(&ctx, password_buf, 32 + engineLength);
  john_MD5_Final(key, &ctx);
}


