void compute_grid_red(double **grid, int gridsize, int strip_size, int myrank)
{
  int i;
  int j;
  int jstart;
  #pragma omp parallel for shared(grid,num_threads) private(i,j,jstart) schedule (static, chunk_size)
  for (i = 1; i < (strip_size - 1); i++)
  {
    if ((i % 2) == 1)
      jstart = 1;
    else
      jstart = 2;

