  fnew = compute_f(u, d, rho, y, N);
  if ((fnew < 0) && (fabs(fnew) > (0.1 * fabs(fpre))))
    fixed = 0;

  while ((!stopcriteria) && (res.iter < 3))
  {
    if ((d[k] < y) && (y < ((d[k] + d[k + 1]) / 2)))
    {
      K = k;
      tho = y - d[k];
    }
    else
      if ((((d[k] + d[k + 1]) / 2) < y) && (y < d[k + 1]))
    {
      K = k + 1;
      tho = d[k + 1] - y;
    }


    fK = fnew - ((u[K] * u[K]) / (-tho));
    if (fK > 0)
    {
      if (fixed)
        y = fixed_weight_f(u, d, rho, y, N, k);
      else
        y = middle_way_f(u, d, rho, y, N, k);

    }
    else
    {
      if (fixed)
        y = fixed_weight_fm(u, d, rho, y, N, k);
      else
        y = middle_way_fm(u, d, rho, y, N, k);

    }

    fpre = fnew;
    fnew = compute_f(u, d, rho, y, N);
    if (((fnew * fpre) > 0) && (fabs(fnew) > (0.1 * fabs(fpre))))
      fixed = !fixed;

    res.iter++;
  }

  res.lambda = y;
  return res;
}

