void element_matrices(vertices, prop, Ke, Me)
double vertices[][3];
double Ke[][12];
double Me[];
struct properties *prop;
{
  double ds[3][4];
  double sum[3];
  double jacobian[3][3];
  double det;
  double volume;
  double E;
  double nu;
  double c1;
  double c2;
  double c3;
  double tt;
  double ts;
  int i;
  int j;
  int m;
  int n;
  int row;
  int column;
