  for (i = 0; i < 3; i++)
    for (j = 0; j < 3; j++)
  {
    sum[0] = 0.0;
    for (m = 0; m < 4; m++)
      sum[0] = sum[0] + (ds[i][m] * vertices[m][j]);

    jacobian[j][i] = sum[0];
  }


  inv_J(jacobian, &det);
  for (m = 0; m < 4; m++)
  {
    for (i = 0; i < 3; i++)
    {
      sum[i] = 0.0;
      for (j = 0; j < 3; j++)
        sum[i] = sum[i] + (jacobian[j][i] * ds[j][m]);

    }

    for (i = 0; i < 3; i++)
      ds[i][m] = sum[i];

  }

  volume = det / 6.0;
  if (volume <= 0)
  {
    fprintf(stderr, "Warning: Element volume = %f !\n", volume);
  }

  get_Enu(prop, &E, &nu);
  c1 = (E / ((2.0 * (nu + 1.0)) * (1.0 - (nu * 2.0)))) * volume;
  c2 = ((E * nu) / ((nu + 1.0) * (1.0 - (nu * 2.0)))) * volume;
  c3 = (E / ((nu + 1.0) * 2.0)) * volume;
  row = -1;
  for (m = 0; m < 4; m++)
  {
    for (i = 0; i < 3; ++i)
    {
      ++row;
      column = -1;
      for (n = 0; n <= m; n++)
      {
        for (j = 0; j < 3; j++)
        {
          ++column;
          ts = ds[i][m] * ds[j][n];
          if (i == j)
          {
            ts = ts * c1;
            tt = (((ds[0][m] * ds[0][n]) + (ds[1][m] * ds[1][n])) + (ds[2][m] * ds[2][n])) * c3;
          }
          else
