              tt = 0;
            }
            else
            {
              ts = ts * c2;
              tt = (ds[j][m] * ds[i][n]) * c3;
            }

          }

          Ke[row][column] = (Ke[row][column] + ts) + tt;
        }

      }

    }

  }

  tt = (prop->den * volume) / 4.0;
  for (i = 0; i < 12; i++)
    Me[i] = tt;

  for (i = 0; i < 12; i++)
    for (j = 0; j <= i; j++)
    Ke[j][i] = Ke[i][j];


}


