{
  double deltax = 0.2;
  double deltay = 0.2;
  double deltar = 0.2;
  double converge = 0.1;
  double lambdaedge = 1;
  double lambdasize = 0.2;
  double lambdapath = 0.05;
  int iterations = 1000;
  int i;
  int j;
  double xc = *xc0;
  double yc = *yc0;
  double *r = (double *) malloc((sizeof(double)) * Np);
  for (i = 0; i < Np; i++)
    r[i] = r0[i];

