  MAT *fy = gradient_y(f);
  int fh = f->m;
  int fw = f->n;
  for (i = 0; i < fh; i++)
  {
    for (j = 0; j < fw; j++)
    {
      double temp_x = fx->me[i][j];
      double temp_y = fy->me[i][j];
      double fmag = sqrt((temp_x * temp_x) + (temp_y * temp_y));
      fx->me[i][j] = temp_x / fmag;
      fy->me[i][j] = temp_y / fmag;
    }

  }

  double *r_old = (double *) malloc((sizeof(double)) * Np);
  VEC *x = v_get(Np);
  VEC *y = v_get(Np);
  int iter = 0;
