      y->ve[i] = yc + (r[i] * sin(t[i]));
    }

    double min_x = x->ve[0];
    double max_x = x->ve[0];
    double min_y = y->ve[0];
    double max_y = y->ve[0];
    for (i = 1; i < Np; i++)
    {
      double x_i = x->ve[i];
      if (x_i < min_x)
        min_x = x_i;
      else
        if (x_i > max_x)
        max_x = x_i;


      double y_i = y->ve[i];
