      r_diff += fabs(r[i] - r_old[i]);
    }

    snakediff = (fabs(xc - xc_old) + fabs(yc - yc_old)) + r_diff;
    m_free(vf);
    m_free(vfx);
    m_free(vfy);
    m_free(vfr);
    iter++;
  }

  *xc0 = xc;
  *yc0 = yc;
  for (i = 0; i < Np; i++)
    r0[i] = r[i];

  free(r);
  free(r_old);
  v_free(x);
  v_free(y);
  m_free(fx);
  m_free(fy);
}

