  int zhi = ((order_3d >> ((oct * 3) + 2)) & 1) ? (nz) : (0);
  int istep = (xhi == nx) ? (-1) : (1);
  int jstep = (yhi == ny) ? (-1) : (1);
  int kstep = (zhi == nz) ? (-1) : (1);
