  double *l_flux_in = (((timestep % 2) == 0) ? (flux_in) : (flux_out)) + offset;
  double *l_flux_out = (((timestep % 2) == 0) ? (flux_out) : (flux_in)) + offset;
  int cells_processed = 0;
  #pragma omp target data if(OFFLOAD) device(MIC_DEVICE) map(to: cells[:ichunk*ny*nz])
  for (unsigned int d = 0; d < ndiag; d++)
  {
    int ncells = num_cells[d];
    sweep_cell(istep, jstep, kstep, oct, l_flux_in, l_flux_out, &cells[cells_processed], groups_todo, num_groups_todo, ncells);
