void update(car *cars, int *grid, int *new_grid, parameters *sim, unsigned short **xsubi)
{
  #pragma omp parallel for
  for (int i = 0; i < sim->LANES; i++)
  {
    for (int j = 0; j < sim->L; j++)
    {
      new_grid[(sim->L * i) + j] = -1;
    }

  }

  #pragma omp parallel
  {
    #pragma omp for
    for (int i = 0; i < sim->N; i++)
    {
      cars[i].lane_change_prev = cars[i].lane_change_now;
      if ((((erand48(xsubi[omp_get_thread_num()]) < sim->p_change) && (gapAhead(cars, i, grid, sim) < aheadThisLane(cars, i, sim))) && (gapAheadOther(cars, i, grid, sim) > aheadOtherLane(cars, i, sim))) && (gapBehindOther(cars, i, grid, sim) > behindOtherLane(cars, i, sim)))
      {
        cars[i].y = (cars[i].y + 1) % sim->LANES;
        cars[i].lane_change_now = 1;
      }
      else
      {
        cars[i].lane_change_now = 0;
      }

      new_grid[(sim->L * cars[i].y) + cars[i].x] = i;
    }

    int gap;
    #pragma omp for private(gap)
    for (int i = 0; i < sim->N; i++)
    {
      gap = gapAhead(cars, i, new_grid, sim);
      if (cars[i].v < cars[i].v_d)
      {
        cars[i].v++;
      }

      if (cars[i].v > gap)
      {
        cars[i].v = gap;
      }

      if ((cars[i].v > 0) && (erand48(xsubi[omp_get_thread_num()]) < sim->p_brake))
      {
        cars[i].v--;
      }

    }

    #pragma omp for
    for (int i = 0; i < sim->LANES; i++)
    {
      for (int j = 0; j < sim->L; j++)
      {
        grid[(sim->L * i) + j] = -1;
      }

    }

    #pragma omp for
    for (int i = 0; i < sim->N; i++)
    {
      cars[i].x = (cars[i].x + cars[i].v) % sim->L;
      grid[(sim->L * cars[i].y) + cars[i].x] = i;
    }

  }
}

