void evolve(void *u, int32_t w, int32_t h)
{
  uint32_t (*univ)[w] = u;
  uint32_t new[h][w];
  memset(new, 0, (h * w) * (sizeof(uint32_t)));
  int32_t x;
  int32_t y;
  int32_t x1;
  int32_t y1;
  int32_t chunk;
  int32_t num_chunks = (w * h) / (GSTEP * GSTEP);
  int32_t chunks_in_row = h / GSTEP;
  int32_t chunks_in_col = w / GSTEP;
  #pragma omp parallel for shared(u, univ, new) firstprivate(w, h, num_chunks, chunks_in_row, chunks_in_col) private(x, x1, y, y1, chunk) schedule(static)
  for (chunk = 0; chunk < num_chunks; chunk++)
  {
    int32_t r_start = GSTEP * (chunk / chunks_in_col);
    int32_t c_start = GSTEP * (chunk % chunks_in_row);
    int32_t r_end = ((r_start + GSTEP) > h) ? (h) : (r_start + GSTEP);
    int32_t c_end = ((c_start + GSTEP) > w) ? (w) : (c_start + GSTEP);
    int32_t r;
    int32_t c;
    for (c = c_start; c < c_end; c += GSTEP)
    {
      for (r = r_start; r < r_end; r += GSTEP)
      {
        for (y = c_start; y < c_end; ++y)
        {
          for (x = r_start; x < r_end; ++x)
          {
            uint32_t alive = 0;
            uint32_t undead = 0;
            for (y1 = y - 1; y1 <= (y + 1); y1++)
            {
              for (x1 = x - 1; x1 <= (x + 1); x1++)
              {
                if ((((y1 >= 0) && (y1 < h)) && (x1 >= 0)) && (x1 < w))
                {
                  alive += univ[y1][x1] == 1;
                  undead += univ[y1][x1] == 2;
                }

              }

            }

            if (univ[y][x] == 1)
            {
              if (undead > 1)
              {
                new[y][x] = 0;
              }
              else
                if ((undead == 1) && (alive > 2))
              {
                new[y][x] = 1;
              }
              else
                if ((undead == 1) && (alive <= 2))
              {
                new[y][x] = 2;
              }
              else
                if (alive > 4)
              {
                new[y][x] = 0;
              }
              else
              {
                new[y][x] = 1;
              }




            }
            else
              if (univ[y][x] == 2)
            {
              if (alive > 3)
              {
                new[y][x] = 0;
              }
              else
                if ((alive == 3) && (undead == 3))
              {
                new[y][x] = 2;
              }
              else
                if (undead > 4)
              {
                new[y][x] = 0;
              }
              else
              {
                new[y][x] = 2;
              }



            }
            else
            {
              if (alive == 3)
              {
                new[y][x] = 1;
              }
              else
                if (undead > 2)
              {
                new[y][x] = 2;
              }
              else
              {
                new[y][x] = 0;
              }


            }


          }

        }

      }

    }

  }

  for (x = 0; x < w; x++)
  {
    for (y = 0; y < h; y++)
    {
      univ[y][x] = new[y][x];
    }

  }

}

