      int o;
      int n;
      int side = 0;
      char curr = part[row][m];
      for (o = row - 1; o <= (row + 1); o++)
      {
        int realo = o;
        if (o == (-1))
          realo = partSize - 1;

        if (o == partSize)
          realo = 0;

        for (n = m - 1; n <= (m + 1); n++)
