          if (part[realo][realn] == 'O')
            side++;

        }

      }

      if (curr == 'O')
      {
        if ((side < 2) || (side > 3))
          nextStep[row][m] = '.';
        else
          nextStep[row][m] = 'O';

      }

      if (curr == '.')
      {
        if (side == 3)
          nextStep[row][m] = 'O';
        else
          nextStep[row][m] = '.';

      }

    }

  }

}

