double compute_f(double *u, double *d, double rho, double lambda_j, int N)
{
  double res1 = 0;
  double res2 = 0;
  int j = 0;
  while ((d[j] < lambda_j) && (j < N))
  {
    res1 += (u[j] * u[j]) / (d[j] - lambda_j);
    j++;
  }

  for (; j < N; j++)
  {
    res2 += (u[j] * u[j]) / (d[j] - lambda_j);
  }

  return 1 + (rho * (res1 + res2));
}

