double serial(double *matrix, int n)
{
  int i;
  int j;
  int k;
  double mult;
  struct timeval t1;
  struct timeval t2;
  double stime;
  gettimeofday(&t1, 0);
  for (i = 0; i < (n - 1); i++)
  {
    if (matrix[(i * (n + 1)) + i] == 0)
    {
      for (j = i + i; j < n; j++)
      {
        if (matrix[(j * (n + 1)) + i] != 0)
        {
          swap_rows(i, j, matrix, n);
          break;
        }

      }

    }

    if (matrix[(i * (n + 1)) + i] == 0)
    {
      printf("Unique solution does not exist\n");
      exit(1);
    }

    for (j = i + 1; j < n; j++)
    {
      mult = matrix[(j * (n + 1)) + i];
      if (mult != 0)
      {
        mult /= matrix[(i * (n + 1)) + i];
        for (k = i; k < (n + 1); k++)
        {
          matrix[(j * (n + 1)) + k] -= mult * matrix[(i * (n + 1)) + k];
        }

      }

    }

  }

  if (matrix[(((n - 1) * (n + 1)) + n) - 1] == 0)
  {
    printf("Unique solution does not exist\n");
    exit(1);
  }

  for (i = n - 1; i >= 0; i--)
  {
    for (j = n - 1; j > i; j--)
    {
      matrix[(i * (n + 1)) + n] -= matrix[(i * (n + 1)) + j] * matrix[(j * (n + 1)) + n];
    }

    matrix[(i * (n + 1)) + n] /= matrix[(i * (n + 1)) + i];
  }

  gettimeofday(&t2, 0);
  stime = (t2.tv_sec - t1.tv_sec) + ((t2.tv_usec - t1.tv_usec) / 1000000.0);
  return stime;
}


