static void password2hash(const char *password, unsigned char *hash, int *key_size)
{
  sph_sha1_context ctx;
  unsigned char output[20 * ((125 + 15) / 16)];
  unsigned char buf[20];
  int i;
  int j;
  int oindex = 0;
  int plength = strlen(password);
  for (i = 0; i <= plength; i += 16)
  {
    sph_sha1_init(&ctx);
    sph_sha1(&ctx, password + i, ((plength - i) < 16) ? (plength - i) : (16));
    for (j = 0; j < 2000; j++)
    {
      sph_sha1_close(&ctx, buf);
      sph_sha1_init(&ctx);
      sph_sha1(&ctx, buf, 20);
    }

    memcpy(output + oindex, buf, 20);
    oindex += 20;
  }

  if (plength < 16)
  {
    memcpy(hash, output, 20);
    *key_size = 20;
  }
  else
    if (plength < 32)
  {
    memcpy(hash, output, 40);
    *key_size = 40;
  }
  else
    if (plength < 48)
  {
    memcpy(hash, output, 56);
    *key_size = 56;
  }
  else
  {
    memcpy(hash + (14 * 0), output + 0, 14);
    memcpy(hash + (14 * 1), output + 20, 14);
    memcpy(hash + (14 * 2), output + 40, 14);
    *key_size = 56;
  }



}


