  jtr_sha512_ctx opad;
  _pbkdf2_sha512_load_hmac(K, KL, &ipad, &opad);
  loops = ((skip_bytes + outlen) + (64 - 1)) / 64;
  loop = (skip_bytes / 64) + 1;
  skip_bytes %= 64;
  while (loop <= loops)
  {
    _pbkdf2_sha512(S, SL, R, tmp.x64, loop, &ipad, &opad);
    for (i = skip_bytes; (i < 64) && (accum < outlen); i++)
    {
      out[accum++] = ((uint8_t *) tmp.out)[i];
    }

    loop++;
    skip_bytes = 0;
  }

}


