int ClipVelocity(vec3_t in, vec3_t normal, vec3_t out, float overbounce)
{
  float backoff;
  float change;
  int i;
  int blocked;
  blocked = 0;
  if (normal[2] > 0)
    blocked |= 1;

  if (!normal[2])
    blocked |= 2;

  backoff = (((in[0] * normal[0]) + (in[1] * normal[1])) + (in[2] * normal[2])) * overbounce;
  for (i = 0; i < 3; i++)
  {
    change = normal[i] * backoff;
    out[i] = in[i] - change;
    if ((out[i] > (-0.1)) && (out[i] < 0.1))
      out[i] = 0;

  }

  return blocked;
}

