double mandelbrot(double x, double y)
{
  int maxIteration = 1000;
  int iteration = 0;
  double re = 0;
  double im = 0;
  while ((((re * re) + (im * im)) <= 4) && (iteration < maxIteration))
  {
    double temp = ((re * re) - (im * im)) + x;
    im = ((2 * re) * im) + y;
    re = temp;
    iteration++;
  }

  if (iteration != maxIteration)
    return WHITE;
  else
    return BLACK;

}

