void abe_matrix(vertices, bv, prop, Ce)
double vertices[][3];
int bv[];
struct properties *prop;
double Ce[];
{
  int i;
  int j;
  double area;
  area = area_triangle(vertices);
  for (i = 0; i < 3; i++)
  {
    j = 3 * bv[i];
    Ce[j] = Ce[j] + (((prop->cs * prop->den) * area) / 3.0);
    Ce[j + 1] = Ce[j + 1] + (((prop->cs * prop->den) * area) / 3.0);
    Ce[j + 2] = Ce[j + 2] + (((prop->cp * prop->den) * area) / 3.0);
  }

}


void element_matrices(vertices, prop, Ke, Me)
double vertices[][3];
double Ke[][12];
double Me[];
struct properties *prop;
{
  double ds[3][4];
  double sum[3];
  double jacobian[3][3];
  double det;
  double volume;
  double E;
  double nu;
  double c1;
  double c2;
  double c3;
  double tt;
  double ts;
  int i;
  int j;
  int m;
  int n;
  int row;
  int column;
  shape_ders(ds);
  for (i = 0; i < 3; i++)
    for (j = 0; j < 3; j++)
  {
    sum[0] = 0.0;
    for (m = 0; m < 4; m++)
      sum[0] = sum[0] + (ds[i][m] * vertices[m][j]);

    jacobian[j][i] = sum[0];
  }


  inv_J(jacobian, &det);
  for (m = 0; m < 4; m++)
  {
    for (i = 0; i < 3; i++)
    {
      sum[i] = 0.0;
      for (j = 0; j < 3; j++)
        sum[i] = sum[i] + (jacobian[j][i] * ds[j][m]);

    }

    for (i = 0; i < 3; i++)
      ds[i][m] = sum[i];

  }

  volume = det / 6.0;
