void AntRun(int ant, int starting_city, int repetitions)
{
  if (0 == 1)
    printf(">> Ant #%d is now running...\n", ant);

  double totDist = 0.0;
  int visited_cities = 1;
  int current_city = starting_city;
  AntsPaths[ant][0] = starting_city;
  AntsPaths[ant][10000] = starting_city;
  bool TheAntHasVisitiedCity[10000];
  for (int i = 0; i < 10000; i++)
    TheAntHasVisitiedCity[i] = 0;

  TheAntHasVisitiedCity[starting_city] = 1;
  do
  {
    if (0 == 1)
      printf("\r>> Progress: %.2f%%", (100 * (visited_cities + 1)) / ((float) 10000));

    TheAntHasVisitiedCity[current_city] = 1;
    double highest_decision_value = 0.0;
    int next_city = -1;
    for (int i = 0; i < 10000; i++)
    {
      if (TheAntHasVisitiedCity[i])
        continue;

      unsigned seed = (((3 * ant) + (17 * omp_get_thread_num())) + (22 * repetitions)) + (1112 * omp_get_wtime());
      double random_number = ((float) rand_r(&seed)) / ((float) 32767);
      double decision_value = random_number * Possibility(ant, current_city, i, visited_cities, TheAntHasVisitiedCity);
      if (decision_value > highest_decision_value)
      {
        next_city = i;
        highest_decision_value = decision_value;
      }

    }

    AntsPaths[ant][visited_cities++] = next_city;
    totDist += Distance(current_city, next_city);
    current_city = next_city;
  }
  while (visited_cities < 10000);
  totDist += Distance(current_city, starting_city);
  DistanceTravelled[ant] = totDist;
  if (0 == 1)
    printf(" ===> Finished\n");

}

