int withinTol(double *array)
{
  int flag = 1;
  double median = 0;
  for (int i = 0; i < 3; i++)
  {
    median += array[i];
  }

  median = median / 3;
  for (int i = 0; i < 3; i++)
  {
    flag &= fabs(array[i] - median) <= (0.05 * median);
  }

  return flag;
}

