static void S2KPGPWDE(char *password, unsigned char *salt, unsigned char *key, int key_length)
{
  sph_sha1_context ctx;
  uint32_t num = ((key_length - 1) / 20) + 1;
  int i;
  int j;
  uint32_t bytes;
  int slen;
  const unsigned char b = 0;
  uint32_t cbytes = cur_salt->bytes;
  slen = strlen(password);
  if (cbytes < (slen + 16))
    cbytes = (uint32_t) (slen + 16);

  for (i = 0; i < num; i++)
  {
    bytes = cbytes;
    sph_sha1_init(&ctx);
    for (j = 0; j < i; j++)
    {
      sph_sha1(&ctx, &b, 1);
    }

    while (bytes > (slen + 16))
    {
      sph_sha1(&ctx, salt, 16);
      sph_sha1(&ctx, password, slen);
      bytes -= slen + 16;
    }

    if (bytes <= 16)
    {
      sph_sha1(&ctx, salt, bytes);
    }
    else
    {
      sph_sha1(&ctx, salt, 16);
      sph_sha1(&ctx, password, bytes - 16);
    }

    sph_sha1_close(&ctx, key + (i * 20));
  }

}

