      old = arr[C];
      new = (((arr[N] + arr[S]) + arr[W]) + arr[E]) / 4.0;
      if (((((new - old) > 0.0) ? (new - old) : ((-new) - old)) / (((new > 0.0) ? (new) : (-new)) + SMALL)) > eps)
      {
        not_precise = 1;
      }

      arr[C] = new;
    }

  }

  #pragma omp parallel for private(j, old, new, C, N, E, S, W) reduction(+:not_precise)
  for (i = 1; i < (maxI - 1); i++)
  {
    for (j = 1; j < (maxJ - 1); j++)
    {
      if (!((i + j) & 1))
        continue;

      C = (i * maxJ) + j;
      N = ((i - 1) * maxJ) + j;
      E = (i * maxJ) + (j + 1);
      S = ((i + 1) * maxJ) + j;
      W = (i * maxJ) + (j - 1);
      old = arr[C];
      new = (((arr[N] + arr[S]) + arr[W]) + arr[E]) / 4.0;
      if (((((new - old) > 0.0) ? (new - old) : ((-new) - old)) / (((new > 0.0) ? (new) : (-new)) + SMALL)) > eps)
      {
        not_precise = 1;
      }

      arr[C] = new;
    }

  }

  return !not_precise;
}


