static void pbkdf2_sha256(const unsigned char *K, int KL, unsigned char *S, int SL, int R, unsigned char *out, int outlen, int skip_bytes)
{
  union 
  {
    uint32_t x32[32 / (sizeof(uint32_t))];
    unsigned char out[32];
  } tmp;
  int loop;
  int loops;
  int i;
  int accum = 0;
  jtr_sha256_ctx ipad;
  jtr_sha256_ctx opad;
  _pbkdf2_sha256_load_hmac(K, KL, &ipad, &opad);
  loops = ((skip_bytes + outlen) + (32 - 1)) / 32;
  loop = (skip_bytes / 32) + 1;
  skip_bytes %= 32;
  while (loop <= loops)
  {
    _pbkdf2_sha256(S, SL, R, tmp.x32, loop, &ipad, &opad);
    for (i = skip_bytes; (i < 32) && (accum < outlen); i++)
    {
      out[accum++] = ((uint8_t *) tmp.out)[i];
    }

    loop++;
    skip_bytes = 0;
  }

}


static int fvde_decrypt(fvde_custom_salt *cur_salt, unsigned char *key)
{
  uint64_t *C = cur_salt->blob.qword;
  int n = (40 / 8) - 1;
  uint64_t R[5];
  union 
  {
    uint64_t qword[2];
    unsigned char stream[16];
  } todecrypt;
  int i;
  int j;
  AES_KEY akey;
  uint64_t A = C[0];
  if (cur_salt->type == 1)
  {
    JTR_AES_set_decrypt_key(key, 128, &akey);
    n = 2;
  }
  else
  {
    JTR_AES_set_decrypt_key(key, 256, &akey);
  }

  for (i = 0; i < (n + 1); i++)
    R[i] = C[i];

  for (j = 5; j >= 0; j--)
  {
    for (i = n; i >= 1; i--)
    {
      todecrypt.qword[0] = A ^ ((n * j) + i);
      todecrypt.qword[1] = R[i];
      (0 == 1) ? (JTR_AES_encrypt(todecrypt.stream, todecrypt.stream, &akey)) : (JTR_AES_decrypt(todecrypt.stream, todecrypt.stream, &akey));
      A = todecrypt.qword[0];
      R[i] = todecrypt.qword[1];
    }

  }

  if (A == 0xa6a6a6a6a6a6a6a6ULL)
    return 1;

  return 0;
}

