void six_color_tree(graph *g, int digits)
{
  do
  {
    fprintf(stdout, "[debug] %s:%d:%s(): starting\n", basename("/home/reemh/CLPP/github-clone-all/repos_final/amannougrahiya/imop-compiler/tests/imsuite/src/vertex_coloring.c"), 143, __func__);
  }
  while (0);
  parent_to_child(g);
  #pragma omp parallel for schedule(SCHEDULING_METHOD)
  for (int i = 0; i < g->N; i++)
  {
    node *u = elem_at(&g->vertices, i);
    payload *u_data = u->data;
    if (u->label == ROOT)
      continue;

    u_data->again = 0;
    int xor = u_data->recv ^ u_data->color;
    for (int k = 0; k < digits; k++)
    {
      int mask = 1 << k;
