  }

  if (!disagreement)
    do
  {
    fprintf(stdout, "[info] %s:%d:%s(): Correct! All nodes have agreed to have %d as the leader.\n", basename("/home/reemh/CLPP/github-clone-all/repos_final/amannougrahiya/imop-compiler/tests/imsuite/src/leader_elect_dp.c"), 115, __func__, leader);
  }
  while (0);

  return disagreement;
}

