inline static void compute_hash(const psk_entry *psk_params, char *password, unsigned char *hash_r)
{
  size_t password_len = strlen(password);
  unsigned char skeyid[20];
  if (psk_params->nortel_user[0] == 0)
  {
    if (psk_params->hash_type == 1)
    {
      hmac_md5((unsigned char *) psk_params->skeyid_data, psk_params->skeyid_data_len, (unsigned char *) password, password_len, skeyid);
    }
    else
    {
      hmac_sha1(psk_params->skeyid_data, psk_params->skeyid_data_len, (unsigned char *) password, password_len, skeyid);
    }

  }
  else
  {
    unsigned char nortel_psk[20];
    unsigned char nortel_pwd_hash[20];
    sph_sha1_context ctx;
    sph_sha1_init(&ctx);
    sph_sha1(&ctx, password, password_len);
    sph_sha1_close(&ctx, nortel_pwd_hash);
    hmac_sha1((unsigned char *) psk_params->nortel_user, strlen(psk_params->nortel_user), nortel_pwd_hash, 20, nortel_psk);
    if (psk_params->hash_type == 1)
    {
      hmac_md5((unsigned char *) psk_params->skeyid_data, psk_params->skeyid_data_len, nortel_psk, 20, skeyid);
    }
    else
    {
      hmac_sha1(psk_params->skeyid_data, psk_params->skeyid_data_len, nortel_psk, 20, skeyid);
    }

  }

  if (psk_params->hash_type == 1)
  {
    hmac_md5((unsigned char *) psk_params->hash_r_data, psk_params->hash_r_data_len, skeyid, psk_params->hash_r_len, hash_r);
  }
  else
  {
    hmac_sha1(psk_params->hash_r_data, psk_params->hash_r_data_len, skeyid, psk_params->hash_r_len, hash_r);
  }

}

