  if (matB)
  {
    for (i = 0; i < n; i++)
    {
      matB[i] = malloc((sizeof(*matB[i])) * n);
    }

  }

  double **matC = malloc((sizeof(*matC)) * n);
  if (matC)
  {
    for (i = 0; i < n; i++)
    {
      matC[i] = malloc((sizeof(*matC[i])) * n);
    }

  }

  srand(time(0));
  for (i = 0; i < n; i++)
  {
    for (j = 0; j < n; j++)
    {
      a = ((double) rand()) / 1000000;
      matA[i][j] = a;
    }

  }

  for (i = 0; i < n; i++)
  {
    for (j = 0; j < n; j++)
    {
      a = ((double) rand()) / 1000000;
      matB[i][j] = a;
    }

  }

  double start = omp_get_wtime();
  transpose(matB, n);
  #pragma omp parallel for
  for (int i = 0; i < n; i++)
  {
    #pragma omp parallel for
    for (int j = 0; j < n; j++)
    {
      double sum = 0.0;
      for (int k = 0; k < n; k++)
      {
        sum += matA[i][k] * matB[j][k];
      }

      matC[i][j] = sum;
    }

  }

  double end = omp_get_wtime();
  double seconds = end - start;
  printf("\n%lf", seconds);
  free(matA);
  free(matB);
  free(matC);
  return seconds;
}

