void c_fft1d(complex *r, int n, int isign)
{
  int m = 0;
  int i = 0;
  int i1 = 0;
  int j = 0;
  int k = 0;
  int i2 = 0;
  int l = 0;
  int l1 = 0;
  int l2 = 0;
  float c1;
  float c2;
  float z;
  complex t;
  complex u;
  if (isign == 0)
  {
    return;
  }

  i2 = n >> 1;
  j = 0;
  for (i = 0; i < (n - 1); i++)
  {
    if (i < j)
    {
      ctmp = r[i];
      r[i] = r[j];
      r[j] = ctmp;
    }

    ;
    k = i2;
    while (k <= j)
    {
      j -= k;
      k >>= 1;
    }

    j += k;
  }

  for (i = n, m = 0; i > 1; m++, i /= 2)
    ;

  c1 = -1.0;
  c2 = 0.0;
  l2 = 1;
  for (l = 0; l < m; l++)
  {
    l1 = l2;
    l2 <<= 1;
    u.r = 1.0;
    u.i = 0.0;
    for (j = 0; j < l1; j++)
    {
      for (i = j; i < n; i += l2)
      {
        i1 = i + l1;
        t.r = (u.r * r[i1].r) - (u.i * r[i1].i);
        t.i = (u.r * r[i1].i) + (u.i * r[i1].r);
        r[i1].r = r[i].r - t.r;
        r[i1].i = r[i].i - t.i;
        r[i].r += t.r;
        r[i].i += t.i;
      }

      z = (u.r * c1) - (u.i * c2);
      u.i = (u.r * c2) + (u.i * c1);
      u.r = z;
    }

    c2 = sqrt((1.0 - c1) / 2.0);
    if (isign == (-1))
      c2 = -c2;

    c1 = sqrt((1.0 + c1) / 2.0);
  }

  if (isign == 1)
  {
    for (i = 0; i < n; i++)
    {
      r[i].r /= n;
      r[i].i /= n;
    }

  }

}

