double filter(int d, int i, int j)
{
  double rd4sq;
  double rsq;
  double sigmad4sq;
  double sigmasq;
  double x;
  double y;
  double delta;
  int d4 = 4;
  double sigmad4 = 1.4;
  double filter0 = -40.0;
  rd4sq = d4 * d4;
  rsq = d * d;
  sigmad4sq = sigmad4 * sigmad4;
  sigmasq = sigmad4sq * (rsq / rd4sq);
  x = (double) i;
  y = (double) j;
  rsq = (x * x) + (y * y);
  delta = rsq / (2.0 * sigmasq);
  return (filter0 * (1.0 - delta)) * exp(-delta);
}

