int mandel_val(double x, double y, int max_iter)
{
  int j = 1;
  double temp_real;
  double cr;
  double p_real = x;
  double ci;
  double p_imag = y;
  cr = x * x;
  ci = y * y;
  while (((cr + ci) <= 4) && (j < max_iter))
  {
    temp_real = (cr - ci) + x;
    p_imag = ((2 * p_real) * p_imag) + y;
    p_real = temp_real;
    j++;
    cr = p_real * p_real;
    ci = p_imag * p_imag;
  }

  if ((cr + ci) <= 4)
    return -1;
  else
    return j;

}

