void sort(int arr[], int beg, int end)
{
  if (end > (beg + 1))
  {
    int piv = arr[beg];
    int l = beg + 1;
    int r = end;
    while (l < r)
    {
      if (arr[l] <= piv)
        l++;
      else
        swap(&arr[l], &arr[--r]);

    }

    swap(&arr[--l], &arr[beg]);
    sort(arr, beg, l);
    sort(arr, r, end);
  }

}

