    from = i * curr_chunk;
    to = ((i * curr_chunk) + curr_chunk) - 1;
    insert_sort(*array, (from < (size - 1)) ? (from) : (size - 1), (to < (size - 1)) ? (to) : (size - 1));
  }

  merge_arrays(*array, array_new, size, count_threads, curr_chunk);
  free(*array);
  *array = array_new;
