double calculate_b(int argc, int it, int iterations)
{
  const double middle = 1.5;
  const double disp = 0.1;
  const double step = disp / iterations;
  return (argc > 1) ? ((middle - (disp / 2)) + (step * it)) : (((double) it) / iterations);
}


void run_through(double *res, int size, double **A, double *f, double *y_pr, double *alpha_pr, double *betta_pr)
