    y_pr[i] = A[i][i] + (A[i - 1][i] * alpha_pr[i - 1]);
    alpha_pr[i] = (-A[i + 1][i]) / y_pr[i];
    betta_pr[i] = (f[i] - (A[i - 1][i] * betta_pr[i - 1])) / y_pr[i];
  }

  y_pr[size - 1] = A[size - 1][size - 1] + (A[size - 2][size - 1] * alpha_pr[size - 2]);
  betta_pr[size - 1] = (f[size - 1] - (A[size - 2][size - 1] * betta_pr[size - 2])) / y_pr[size - 1];
  res[size - 1] = betta_pr[size - 1];
