      averageR = 0;
      averageG = 0;
      averageB = 0;
      for (int itImageX = i - (maskDimensions / 2), itMaskX = 0; (itImageX <= (i + (maskDimensions / 2))) && (itMaskX < maskDimensions); itImageX++, itMaskX++)
