          {
            int px = &row[itImageY * 4];
            if ((((itImageX >= 0) && (itImageX < height)) && (itImageY >= 0)) && (itImageY < width))
            {
              averageR += px[0] * maskMatrix[itMaskX][itMaskY];
              averageG += px[1] * maskMatrix[itMaskX][itMaskY];
