      if (curr_res < final_res)
      {
        copyToFinal(curr_pat);
        final_res = curr_res;
      }

    }

    return;
  }

  int i;
  #pragma omp parallel for default(none) firstprivate(curr_bound, curr_weight, level) shared(curr_pat, vis,adj,final_res,N)
  for (i = 0; i < N; i++)
