void assign_pixels(byte_t *data, double *centers, int *labels, double *dists, int *changes, int n_px, int n_ch, int n_clus)
{
  int px;
  int ch;
  int k;
  int min_k;
  int tmp_changes = 0;
  double dist;
  double min_dist;
  double tmp;
  #pragma omp parallel for schedule(static) private(px, ch, k, min_k, dist, min_dist, tmp)
  for (px = 0; px < n_px; px++)
  {
    min_dist = DBL_MAX;
    for (k = 0; k < n_clus; k++)
    {
      dist = 0;
      for (ch = 0; ch < n_ch; ch++)
      {
        tmp = (double) (data[(px * n_ch) + ch] - centers[(k * n_ch) + ch]);
        dist += tmp * tmp;
      }

      if (dist < min_dist)
      {
        min_dist = dist;
        min_k = k;
      }

    }

    dists[px] = min_dist;
    if (labels[px] != min_k)
    {
      labels[px] = min_k;
      tmp_changes = 1;
    }

  }

  *changes = tmp_changes;
}


void update_centers(byte_t *data, double *centers, int *labels, double *dists, int n_px, int n_ch, int n_clus)
{
  int px;
  int ch;
  int k;
  int *counts;
  int min_k;
  int far_px;
  double max_dist;
  counts = malloc(n_clus * (sizeof(int)));
  for (k = 0; k < n_clus; k++)
  {
    for (ch = 0; ch < n_ch; ch++)
    {
      centers[(k * n_ch) + ch] = 0;
    }

    counts[k] = 0;
  }

  #pragma omp parallel for private(px, ch, min_k) reduction(+:centers[:n_clus * n_ch],counts[:n_clus])
  for (px = 0; px < n_px; px++)
  {
    min_k = labels[px];
    for (ch = 0; ch < n_ch; ch++)
    {
      centers[(min_k * n_ch) + ch] += data[(px * n_ch) + ch];
    }

    counts[min_k]++;
  }

  for (k = 0; k < n_clus; k++)
  {
    if (counts[k])
    {
      for (ch = 0; ch < n_ch; ch++)
      {
        centers[(k * n_ch) + ch] /= counts[k];
      }

    }
    else
    {
      max_dist = 0;
      for (px = 0; px < n_px; px++)
      {
        if (dists[px] > max_dist)
        {
          max_dist = dists[px];
          far_px = px;
        }

      }

      for (ch = 0; ch < n_ch; ch++)
      {
        centers[(k * n_ch) + ch] = data[(far_px * n_ch) + ch];
      }

      dists[far_px] = 0;
    }

  }

  free(counts);
}

