void smith_waterman_forward(char *x, char *y, int m, int n, int score[m][n], int pred[m][n], int i, int j)
{
  int diagonal;
  int left;
  int up;
  if (x[i - 1] == y[j - 1])
  {
    diagonal = score[i - 1][j - 1] + MATCH;
  }
  else
  {
    diagonal = score[i - 1][j - 1] + MISMATCH;
  }

  up = score[i - 1][j] + SPACE;
  left = score[i][j - 1] + SPACE;
  if (max(0, max(diagonal, max(up, left))) == 0)
  {
    score[i][j] = 0;
    pred[i][j] = 0;
  }
  else
    if ((diagonal >= up) && (diagonal >= left))
  {
    score[i][j] = diagonal;
    pred[i][j] = 1;
  }
  else
    if ((left >= diagonal) && (left >= up))
  {
    score[i][j] = left;
    pred[i][j] = 2;
  }
  else
  {
    score[i][j] = up;
    pred[i][j] = 3;
  }



}

