void Merge_Sort(int a[], int b[], int lo, int hi)
{
  int temp;
  int mid;
  if (lo < hi)
  {
    if (hi == (lo + 1))
    {
      if (a[hi] < a[lo])
      {
        temp = a[hi];
        a[hi] = a[lo];
        a[lo] = temp;
      }

    }
    else
    {
      mid = (lo + hi) / 2;
      Merge_Sort(a, b, lo, mid);
      Merge_Sort(a, b, mid + 1, hi);
      Merge(a, b, lo, mid, hi);
    }

  }

}

