void sequentialOddEven(int *arr, int size)
{
  int i;
  int tmp;
  bool isSorted = 0;
  while (!isSorted)
  {
    isSorted = 1;
    for (i = 0; i <= (size - 2); i = i + 2)
    {
      if (arr[i] > arr[i + 1])
      {
        tmp = arr[i];
        arr[i] = arr[i + 1];
        arr[i + 1] = tmp;
        isSorted = 0;
      }

    }

    for (i = 1; i <= (size - 2); i = i + 2)
    {
      if (arr[i] > arr[i + 1])
      {
        tmp = arr[i + 1];
        arr[i + 1] = arr[i];
        arr[i] = tmp;
        isSorted = 0;
      }

    }

    if (isSorted)
      break;

  }

}


