    int mask = 1;
    for (i = 0; i < hierarchy->group_size[j]; ++i)
    {
      if (truth[count + i])
      {
        mask = 0;
        break;
      }

    }

    if (mask)
    {
      for (i = 0; i < hierarchy->group_size[j]; ++i)
      {
        truth[count + i] = -1234;
