bool mandelbrot(double x, double y, int precition)
{
  double a = 0;
  double b = 0;
  for (int i = 0; i < precition; i++)
  {
    double real = (pow(a, 2) - pow(b, 2)) + x;
    double img = ((2 * a) * b) + y;
    a = real;
    b = img;
    if (sqrt(pow(a, 2) + pow(b, 2)) > 2.)
    {
      return 0;
    }

  }

  return 1;
}

