    noise.x /= nmag;
    noise.y /= nmag;
    noise.z /= nmag;
    p2.x += 0.0001 * noise.x;
    p2.y += 0.0001 * noise.y;
    p2.z += 0.0001 * noise.z;
    triple r2;
    diff(&r2, g, p2);
    double rmag2 = sqrt((pow(r2.x, 2) + pow(r2.y, 2)) + pow(r2.z, 2));
    r2.x /= rmag2;
    r2.y /= rmag2;
    r2.z /= rmag2;
    int shadow = 0;
    for (int i = 0; i < 4; i++)
    {
      triple vectorc = {a[i].c.x, a[i].c.y, a[i].c.z};
      triple d;
      diff(&d, p2, vectorc);
      double a1 = 1.0;
      double b = 2 * dotp(d, r2);
      double c = ((pow(d.x, 2) + pow(d.y, 2)) + pow(d.z, 2)) - pow(a[i].r, 2);
      double discriminant = pow(b, 2) - ((4 * a1) * c);
      if (discriminant < 0)
        continue;
      else
      {
        double T = ((((-1) * b) - sqrt(discriminant)) / 2) * a1;
        if (T > 0)
        {
          shadow = 1;
          break;
        }

      }

