  sph_sha1_context ctx;
  int fullblocks = size / 20;
  int padding = size % 20;
  for (i = 0; i < fullblocks; i++)
  {
    IV = i;
    sph_sha1_init(&ctx);
    sph_sha1(&ctx, &IV, 4);
    sph_sha1(&ctx, src + (20 * i), 20);
    sph_sha1_close(&ctx, dst + (20 * i));
  }

  if (padding)
  {
    IV = fullblocks;
    sph_sha1_init(&ctx);
    sph_sha1(&ctx, &IV, 4);
    sph_sha1(&ctx, src + (20 * fullblocks), padding);
    sph_sha1_close(&ctx, dst + (20 * fullblocks));
  }

  return 0;
}

