void tour_barrier_init(int vpid, volatile round_t **myrounds)
{
  int k;
  *myrounds = &rounds[vpid][0];
  for (k = 0; k < 3; k++)
    (*myrounds)[k].role = (role_enum) 16;

  for (k = 0; k < 3; k++)
  {
    int vpid_mod_2_sup_k_plus_1 = vpid % (1 << (k + 1));
    if (vpid_mod_2_sup_k_plus_1 == 0)
    {
      int partner = vpid + (1 << k);
      if (partner < 8)
        (*myrounds)[k].role = (role_enum) 2;
      else
        (*myrounds)[k].role = (role_enum) 8;

      (*myrounds)[k].opponent = (boolean *) 0;
    }
    else
      if (vpid_mod_2_sup_k_plus_1 == (1 << k))
    {
      (*myrounds)[k].role = (role_enum) 1;
      (*myrounds)[k].opponent = &rounds[vpid - (1 << k)][k].flag;
      break;
    }


  }

  if (vpid == 0)
  {
    (*myrounds)[k - 1].role = (role_enum) 4;
  }

  for (k = 0; k < 3; k++)
  {
    (*myrounds)[k].flag = (boolean) 0;
  }

}

