int getMedian(int *values, int size)
{
  int middle = size / 2;
  int start = 0;
  int stop = size - 1;
  int pivot = sort(values, start, stop);
  while (pivot != middle)
  {
    if (pivot > middle)
    {
      stop = pivot - 1;
      pivot = sort(values, start, stop);
    }
    else
    {
      start = pivot + 1;
      pivot = sort(values, start, stop);
    }

  }

  return values[pivot];
}

