long getTotient(long number)
{
  long result = number;
  if ((number % 2) == 0)
  {
    result -= result / 2;
    do
      number /= 2;
    while ((number % 2) == 0);
  }

  long prime;
  for (prime = 3; (prime * prime) <= number; prime += 2)
  {
    if ((number % prime) == 0)
    {
      result -= result / prime;
      do
        number /= prime;
      while ((number % prime) == 0);
    }

  }

  if (number > 1)
    result -= result / number;

  return result;
}

