void getCofactor(long **mat, long **temp, int p, int q, int n)
{
  int i = 0;
  int j = 0;
  for (int row = 0; row < n; row++)
  {
    for (int col = 0; col < n; col++)
    {
      if ((row != p) && (col != q))
      {
        temp[i][j++] = mat[row][col];
        if (j == (n - 1))
        {
          j = 0;
          i++;
        }

      }

    }

  }

}


long determinantOfMatrix(long **mat, int n)
{
  long D = 0;
  if (n == 1)
  {
    return mat[0][0];
  }

  long **temp = 0;
  temp = (long **) malloc(n * (sizeof(long)));
  int i = 0;
  int j = 0;
  for (i = 0; i < n; i++)
  {
    temp[i] = (long *) malloc((sizeof(long)) * 10);
  }

  int sign = 1;
  for (j = 0; j < n; j++)
  {
    getCofactor(mat, temp, 0, j, n);
    D += (sign * mat[0][j]) * determinantOfMatrix(temp, n - 1);
    sign = -sign;
  }

  for (i = 0; i < n; i++)
  {
    free(temp[i]);
  }

  free(temp);
  return D;
}

