void rank_is(int iteration)
{
  INT_TYPE i;
  INT_TYPE k;
  INT_TYPE *key_buff_ptr;
  INT_TYPE *key_buff_ptr2;
  int shift = MAX_KEY_LOG_2 - NUM_BUCKETS_LOG_2;
