void loopcode_sub(int i, int n, double mass, double fcon, int delta, double grav, double sep, double rball, double xball, double yball, double zball, double dt, double *x, double *y, double *z, double *fx, double *fy, double *fz, double *vx, double *vy, double *vz, double *oldfx, double *oldfy, double *oldfz, double *pe, double *ke, double *te)
{
