  {
    float diff_v[3] = {(float) x[(j * n) + i], (float) y[(j * n) + i], (float) z[(j * n) + i]};
    int sse_current = _mm_load_ps(diff_v);
    int sse_ball = _mm_load_ps(ball_v);
    int sse_point_ball_diff = _mm_sub_ps(sse_current, sse_ball);
    int sse_diff_mag = _mm_mul_ps(sse_point_ball_diff, sse_point_ball_diff);
    float sum_v[3] = {0.0, 0.0, 0.0};
    _mm_store_ps(sum_v, sse_diff_mag);
    vmag = sqrt((sum_v[0] + sum_v[1]) + sum_v[2]);
    if (vmag < rball)
    {
      float tmp[3] = {(float) (rball / vmag), (float) (rball / vmag), (float) (rball / vmag)};
      int tmp_sse = _mm_load_ps(tmp);
      tmp_sse = _mm_mul_ps(tmp_sse, sse_point_ball_diff);
      sse_current = _mm_add_ps(sse_ball, tmp_sse);
      _mm_store_ps(sum_v, sse_current);
      x[(j * n) + i] = sum_v[0];
      y[(j * n) + i] = sum_v[1];
      z[(j * n) + i] = sum_v[2];
