      float vmag_v[3] = {vmag, vmag, vmag};
      int sse_vmag = _mm_load_ps(vmag_v);
      int sse_r = _mm_div_ps(sse_point_ball_diff, sse_vmag);
      float ball_v[3] = {rball, rball, rball};
