void merge(void *base1, int bnum1, void *base2, int bnum2, size_t bsize, int (*compare)(const void *, const void *))
{
  unsigned char *t;
  unsigned char *c1;
  unsigned char *c2;
  int nr;
  int ns;
  int nt;
  c1 = (unsigned char *) base1;
  c2 = (unsigned char *) base2;
  t = (unsigned char *) malloc(bsize * (bnum1 + bnum2));
  nr = 0;
  ns = 0;
  nt = 0;
  while ((nr < bnum1) && (ns < bnum2))
  {
    if (compare(&c1[nr * bsize], &c2[ns * bsize]) < 0)
    {
      memcpy(&t[nt * bsize], &c1[nr * bsize], bsize);
      nr++;
    }
    else
    {
      memcpy(&t[nt * bsize], &c2[ns * bsize], bsize);
      ns++;
    }

    nt++;
  }

  if (nr < bnum1)
    memcpy(&t[nt * bsize], &c1[nr * bsize], bsize * (bnum1 - nr));
  else
    memcpy(&t[nt * bsize], &c2[ns * bsize], bsize * (bnum2 - ns));

  memcpy(base1, &t[0], bsize * bnum1);
  memcpy(base2, &t[bsize * bnum1], bsize * bnum2);
  free(t);
  return;
}

