  for (int i = 0; i < 100; i++)
  {
    double x = 0;
    #pragma omp simd reduction(+:x)
    for (int j = 0; j < 10; j++)
    {
      x = x + (d2[j] * WL2[j][i]);
    }

    d1[i] = x * ((exp(DL1[i]) / (1 + exp(DL1[i]))) / (1 + exp(DL1[i])));
  }

  #pragma omp parallel for
  for (int i = 0; i < 10; i++)
  {
    #pragma omp simd
    for (int j = 0; j < 100; j++)
    {
      float dw = (0.25 * d2[i]) * OL1[j];
      WL2[i][j] = WL2[i][j] + dw;
    }

  }

  #pragma omp parallel for
  for (int i = 0; i < 100; i++)
  {
    for (int j = 0; j < 754; j++)
