int test_omp_parallel_for_reduction()
{
  int sum;
  int known_sum;
  double dsum;
  double dknown_sum;
  double dt = 0.5;
  double rounding_error = 1.E-9;
  int diff;
  double ddiff;
  int product;
  int known_product;
  int logic_and;
  int logic_or;
  int bit_and;
  int bit_or;
  int exclusiv_bit_or;
