void ProdMatVect(int nc, int nl, double **A, double *x, double *y)
{
  int i;
  int j;
  double somme;
  #pragma omp parallel for
  for (i = 0; i < nl; i++)
  {
    #pragma omp parallel for reduction(+:somme)
    for (j = 0; j < nc; j++)
    {
      somme += A[i][j] * x[j];
    }

    y[i] = somme;
  }

}


void ProdMatMat(int nc, int nl, double **A, double **B, double ***C)
{
  int i;
  int j;
  int k;
  double somme;
  #pragma omp parallel for
  for (i = 0; i < nl; i++)
  {
    #pragma omp parallel for
    for (j = 0; j < nc; j++)
    {
      somme = 0;
      #pragma omp parallel for reduction(+:somme)
      for (k = 0; k < nl; k++)
      {
        somme += A[i][k] * B[k][j];
      }

      (*C)[i][j] = somme;
    }

  }

}

