    new_diagonal = Score[ax - 1][by - 1] + INT2;
  }

  if (new_diagonal == Score[ax][by])
  {
    return traceback(X, Y, ax - 1, by - 1);
  }
  else
    if (new_left == Score[ax][by])
  {
    return traceback(X, Y, ax, by - 1);
  }
  else
  {
    return traceback(X, Y, ax - 1, by);
  }


  return 0;
}


