int calculate_filtered_pixel(int pixel_idx, int *src_array, int width, int height, int *filter)
{
  int sum = 0;
  int j;
  int z = 0;
  int coef = -1;
  for (j = (pixel_idx + (coef * width)) - 1; j <= ((pixel_idx + width) + 1); j++)
  {
    if ((j % width) == ((pixel_idx + 2) % width))
    {
      coef++;
      j = (pixel_idx + (coef * width)) - 2;
      continue;
    }

    sum += (src_array[j] * filter[z]) / 1;
    z++;
  }

  if (sum > 255)
    return 255;
  else
    return sum;

}

