  int file_count = 0;
  if ((dir = opendir(dirname)) == 0)
  {
    fprintf(stderr, "Error : Failed to open input directory - %s\n", strerror(errno));
    return -1;
  }

  while (in_file = readdir(dir))
  {
    if ((((!strcmp(in_file->d_name, ".")) || (!strcmp(in_file->d_name, ".."))) || (!strcmp(in_file->d_name, "./"))) || (!strcmp(in_file->d_name, "../")))
      continue;

    char *file_name = (char *) malloc(((sizeof(char)) * 50) * 3);
    strcpy(file_name, dirname);
    strcat(file_name, directory_seperator);
    strcat(file_name, in_file->d_name);
    if (DEBUG_MODE)
      printf("Queing file: %s\n", file_name);

    #pragma omp critical
    {
      enQueue(file_name_queue, file_name, strlen(file_name));
      file_count++;
    }
  }

  if (DEBUG_MODE)
    printf("Done Queing all files\n\n");

  closedir(dir);
  return file_count;
}

