int binary_search(int array[], int key, int size)
{
  int low = 0;
  int high = size - 1;
  if ((key < array[low]) || (key > array[high]))
  {
    return 0;
  }

  while (low <= high)
  {
    int mid = (low + high) / 2;
    if (array[mid] == key)
    {
      return 1;
    }
    else
      if (key < array[mid])
    {
      high = mid - 1;
    }
    else
    {
      low = mid + 1;
    }


  }

  return 0;
}

