static void crypt_md5(char *pw, char *salt, int is_standard, char *passwd)
{
  const char *magic = (is_standard - 1) ? ("$apr1$") : ("$1$");
  const int magiclen = (is_standard - 1) ? ((sizeof("$apr1$")) - 1) : ((sizeof("$1$")) - 1);
  char *sp;
  char *ep;
  unsigned char final[16];
  int sl;
  int pl;
  int i;
  int j;
  MD5_CTX ctx;
  int pwlen = strlen(pw);
  if (pwlen > 125)
    pwlen = 125;

  sp = salt;
  if (is_standard && (!strncmp(sp, magic, magiclen)))
    sp += magiclen;

  for (ep = sp; ((*ep) && ((*ep) != '$')) && (ep < (sp + 8)); ep++)
    continue;

  sl = ep - sp;
  john_MD5_Init(&ctx);
  john_MD5_Update(&ctx, pw, pwlen);
  john_MD5_Update(&ctx, sp, sl);
  john_MD5_Update(&ctx, pw, pwlen);
  john_MD5_Final(final, &ctx);
  john_MD5_Init(&ctx);
  john_MD5_Update(&ctx, pw, pwlen);
  if (is_standard)
    john_MD5_Update(&ctx, magic, magiclen);

  john_MD5_Update(&ctx, sp, sl);
  for (pl = pwlen; pl > 0; pl -= 16)
    john_MD5_Update(&ctx, final, (pl > 16) ? (16) : (pl));

  for (i = pwlen; i; i >>= 1)
  {
    if (i & 1)
      john_MD5_Update(&ctx, "", 1);
    else
      john_MD5_Update(&ctx, pw, 1);

  }

  john_MD5_Final(final, &ctx);
  unsigned char buf[(8 * 2) + (125 * 3)];
  memcpy(buf, sp, sl);
  memcpy(&buf[sl], pw, pwlen);
  memcpy(&buf[sl + pwlen], pw, pwlen);
  memcpy(&buf[sl + (pwlen << 1)], sp, sl);
  memcpy(&buf[(sl + (pwlen << 1)) + sl], pw, pwlen);
  unsigned char *bufp[6];
  unsigned int bufl[6];
  bufp[0] = &buf[sl];
  bufl[0] = pwlen;
  bufp[1] = bufp[0];
  bufl[1] = pwlen << 1;
  bufp[2] = buf;
  bufl[2] = sl + pwlen;
  bufp[3] = bufp[2];
  bufl[3] = bufl[2] + pwlen;
  bufp[4] = &buf[sl + pwlen];
  bufl[4] = bufl[2];
  bufp[5] = bufp[4];
  bufl[5] = bufl[4] + pwlen;
  static const uint8_t map[42] = {0, 5, 3, 1, 3, 5, 1, 4, 3, 1, 3, 5, 1, 5, 2, 1, 3, 5, 1, 5, 3, 0, 3, 5, 1, 5, 3, 1, 2, 5, 1, 5, 3, 1, 3, 4, 1, 5, 3, 1, 3, 5};
  i = 500;
  j = 0;
  do
  {
    john_MD5_Init(&ctx);
    john_MD5_Update(&ctx, final, 16);
    john_MD5_Update(&ctx, bufp[map[j]], bufl[map[j]]);
    john_MD5_Final(final, &ctx);
    john_MD5_Init(&ctx);
    john_MD5_Update(&ctx, bufp[map[j + 1]], bufl[map[j + 1]]);
    if ((j += 2) >= 42)
      j = 0;

    john_MD5_Update(&ctx, final, 16);
    john_MD5_Final(final, &ctx);
  }
  while (--i);
