void rank(int iteration)
{
  INT_TYPE i;
  INT_TYPE k;
  INT_TYPE *key_buff_ptr;
  INT_TYPE *key_buff_ptr2;
  int shift = 11 - 9;
  INT_TYPE num_bucket_keys = 1L << shift;
  key_array[iteration] = iteration;
  key_array[iteration + 10] = (1 << 11) - iteration;
  for (i = 0; i < 5; i++)
    partial_verify_vals[i] = key_array[test_index_array[i]];

  key_buff_ptr2 = key_buff2;
  key_buff_ptr = key_buff1;
  #pragma omp parallel private(i, k)
  {
    INT_TYPE *work_buff;
    INT_TYPE m;
    INT_TYPE k1;
    INT_TYPE k2;
    int myid = 0;
    int num_procs = 1;
    myid = omp_get_thread_num();
    num_procs = omp_get_num_threads();
    work_buff = bucket_size[myid];
    for (i = 0; i < (1 << 9); i++)
      work_buff[i] = 0;

    #pragma omp for schedule(static)
    for (i = 0; i < (1 << 16); i++)
      work_buff[key_array[i] >> shift]++;

    bucket_ptrs[0] = 0;
    for (k = 0; k < myid; k++)
      bucket_ptrs[0] += bucket_size[k][0];

    for (i = 1; i < (1 << 9); i++)
    {
      bucket_ptrs[i] = bucket_ptrs[i - 1];
      for (k = 0; k < myid; k++)
        bucket_ptrs[i] += bucket_size[k][i];

      for (k = myid; k < num_procs; k++)
        bucket_ptrs[i] += bucket_size[k][i - 1];

    }

    #pragma omp for schedule(static)
    for (i = 0; i < (1 << 16); i++)
    {
      k = key_array[i];
      key_buff2[bucket_ptrs[k >> shift]++] = k;
    }

    if (myid < (num_procs - 1))
    {
      for (i = 0; i < (1 << 9); i++)
        for (k = myid + 1; k < num_procs; k++)
        bucket_ptrs[i] += bucket_size[k][i];


    }

    #pragma omp for schedule(dynamic)
    for (i = 0; i < (1 << 9); i++)
    {
      k1 = i * num_bucket_keys;
      k2 = k1 + num_bucket_keys;
      for (k = k1; k < k2; k++)
        key_buff_ptr[k] = 0;

      m = (i > 0) ? (bucket_ptrs[i - 1]) : (0);
      for (k = m; k < bucket_ptrs[i]; k++)
        key_buff_ptr[key_buff_ptr2[k]]++;

      key_buff_ptr[k1] += m;
      for (k = k1 + 1; k < k2; k++)
        key_buff_ptr[k] += key_buff_ptr[k - 1];

    }

  }
  for (i = 0; i < 5; i++)
  {
    k = partial_verify_vals[i];
    if ((0 < k) && (k <= ((1 << 16) - 1)))
    {
      INT_TYPE key_rank = key_buff_ptr[k - 1];
      int failed = 0;
      switch ('S')
      {
        case 'S':
          if (i <= 2)
        {
          if (key_rank != (test_rank_array[i] + iteration))
            failed = 1;
          else
            passed_verification++;

        }
        else
        {
          if (key_rank != (test_rank_array[i] - iteration))
            failed = 1;
          else
            passed_verification++;

        }

          break;

        case 'W':
          if (i < 2)
        {
          if (key_rank != (test_rank_array[i] + (iteration - 2)))
            failed = 1;
          else
            passed_verification++;

        }
        else
        {
          if (key_rank != (test_rank_array[i] - iteration))
            failed = 1;
          else
            passed_verification++;

        }

          break;

        case 'A':
          if (i <= 2)
        {
          if (key_rank != (test_rank_array[i] + (iteration - 1)))
            failed = 1;
          else
            passed_verification++;

        }
        else
        {
          if (key_rank != (test_rank_array[i] - (iteration - 1)))
            failed = 1;
          else
            passed_verification++;

        }

          break;

        case 'B':
          if (((i == 1) || (i == 2)) || (i == 4))
        {
          if (key_rank != (test_rank_array[i] + iteration))
            failed = 1;
          else
            passed_verification++;

        }
        else
        {
          if (key_rank != (test_rank_array[i] - iteration))
            failed = 1;
          else
            passed_verification++;

        }

          break;

        case 'C':
          if (i <= 2)
        {
          if (key_rank != (test_rank_array[i] + iteration))
            failed = 1;
          else
            passed_verification++;

        }
        else
        {
          if (key_rank != (test_rank_array[i] - iteration))
            failed = 1;
          else
            passed_verification++;

        }

          break;

        case 'D':
          if (i < 2)
        {
          if (key_rank != (test_rank_array[i] + iteration))
            failed = 1;
          else
            passed_verification++;

        }
        else
        {
          if (key_rank != (test_rank_array[i] - iteration))
            failed = 1;
          else
            passed_verification++;

        }

          break;

      }

      if (failed == 1)
        printf("Failed partial verification: iteration %d, test key %d\n", iteration, (int) i);

    }

  }

  if (iteration == 10)
    key_buff_ptr_global = key_buff_ptr;

}

