  for (myrow = 0; myrow < 9; myrow++)
    if (grid[myrow][col] == num)
  {
    alreadyincol = 1;
    myrow = 9;
  }


  bool alreadyinbox = 0;
  int boxStartRow = row - (row % 3);
  int boxStartCol = col - (col % 3);
  for (myrow = 0; myrow < 3; myrow++)
    for (mycol = 0; mycol < 3; mycol++)
