static void conj_grad(int colidx[], int rowstr[], double x[], double z[], double a[], double p[], double q[], double r[], double w[], double *rnorm)
{
  static double d;
  static double sum;
  static double rho;
  static double rho0;
  static double alpha;
  static double beta;
  int i;
  int j;
  int k;
  int cgit;
  int cgitmax = 25;
  #pragma omp single nowait
  rho = 0.0;
  #pragma omp for nowait
  for (j = 1; j <= (naa + 1); j++)
  {
    q[j] = 0.0;
    z[j] = 0.0;
    r[j] = x[j];
    p[j] = r[j];
    w[j] = 0.0;
  }

  #pragma omp for reduction(+:rho)
  for (j = 1; j <= ((lastcol - firstcol) + 1); j++)
  {
    rho = rho + (x[j] * x[j]);
  }

  for (cgit = 1; cgit <= cgitmax; cgit++)
  {
    #pragma omp single nowait
    {
      rho0 = rho;
      d = 0.0;
      rho = 0.0;
    }
    #pragma omp for private(sum,k)
    for (j = 1; j <= ((lastrow - firstrow) + 1); j++)
    {
      sum = 0.0;
      for (k = rowstr[j]; k < rowstr[j + 1]; k++)
      {
        sum = sum + (a[k] * p[colidx[k]]);
      }

      w[j] = sum;
    }

    #pragma omp for
    for (j = 1; j <= ((lastcol - firstcol) + 1); j++)
    {
      q[j] = w[j];
    }

    #pragma omp for nowait
    for (j = 1; j <= ((lastcol - firstcol) + 1); j++)
    {
      w[j] = 0.0;
    }

    #pragma omp for reduction(+:d)
    for (j = 1; j <= ((lastcol - firstcol) + 1); j++)
    {
      d = d + (p[j] * q[j]);
    }

    #pragma omp single
    alpha = rho0 / d;
    #pragma omp for
    for (j = 1; j <= ((lastcol - firstcol) + 1); j++)
    {
      z[j] = z[j] + (alpha * p[j]);
      r[j] = r[j] - (alpha * q[j]);
    }

    #pragma omp for reduction(+:rho)
    for (j = 1; j <= ((lastcol - firstcol) + 1); j++)
    {
      rho = rho + (r[j] * r[j]);
    }

    #pragma omp single
    beta = rho / rho0;
    #pragma omp for
    for (j = 1; j <= ((lastcol - firstcol) + 1); j++)
    {
      p[j] = r[j] + (beta * p[j]);
    }

  }

  #pragma omp single nowait
  sum = 0.0;
  #pragma omp for private(d, k)
  for (j = 1; j <= ((lastrow - firstrow) + 1); j++)
  {
    d = 0.0;
    for (k = rowstr[j]; k <= (rowstr[j + 1] - 1); k++)
    {
      d = d + (a[k] * z[colidx[k]]);
    }

    w[j] = d;
  }

  #pragma omp for
  for (j = 1; j <= ((lastcol - firstcol) + 1); j++)
  {
    r[j] = w[j];
  }

  #pragma omp for reduction(+:sum) private(d)
  for (j = 1; j <= ((lastcol - firstcol) + 1); j++)
  {
    d = x[j] - r[j];
    sum = sum + (d * d);
  }

  #pragma omp single
  {
    *rnorm = sqrt(sum);
  }
}

