  xnew[7] = (*x) - stepSize;
  ynew[7] = (*y) + stepSize;
  withinBounds[7] = (checkWithinBounds((*x) - stepSize, (*y) + stepSize)) ? (1) : (0);
  int totalWithinBounds = 0;
  for (int i = 0; i < 8; i++)
  {
    totalWithinBounds += withinBounds[i];
  }

  if (totalWithinBounds == 0)
  {
    return;
  }

  double max = objectiveFunction(*x, *y);
  int pos = -1;
  for (int i = 0; i < 8; i++)
  {
    if (withinBounds[i])
