double eval_pef_sub(int n, int delta, double grav, double sep, double fcon, double *x, double *y, double *z, double *fx, double *fy, double *fz, int nx)
{
  double pe;
  double rlen;
  double xdiff;
  double ydiff;
  double zdiff;
  double vmag;
  int ny;
  int dx;
  int dy;
  pe = 0.0;
  for (ny = 0; ny < n; ny++)
  {
    for (dx = ((nx - delta) > 0) ? (nx - delta) : (0); dx < ((((nx + delta) + 1) < n) ? ((nx + delta) + 1) : (n)); dx++)
    {
      for (dy = ((ny - delta) > 0) ? (ny - delta) : (0); dy < ((((ny + delta) + 1) < n) ? ((ny + delta) + 1) : (n)); dy++)
      {
        if ((nx != dx) || (ny != dy))
        {
          float n_d[2] = {nx, ny};
          float d_d[2] = {dx, dy};
          float temp_v[3] = {0.0, 0.0, 0.0};
          int s_tmp = _mm_sub_ps(_mm_load_ps(n_d), _mm_load_ps(d_d));
          _mm_store_ps(temp_v, _mm_mul_ps(s_tmp, s_tmp));
          rlen = sqrt(temp_v[0] + temp_v[1]);
          rlen = rlen * sep;
          float d_diff[3] = {(float) x[(dx * n) + dy], (float) y[(dx * n) + dy], (float) z[(dx * n) + dy]};
          float n_diff[3] = {(float) x[(nx * n) + ny], (float) y[(nx * n) + ny], (float) z[(nx * n) + ny]};
          int sse_p = _mm_sub_ps(_mm_load_ps(d_diff), _mm_load_ps(n_diff));
          int s = _mm_mul_ps(sse_p, sse_p);
          _mm_store_ps(temp_v, s);
          vmag = sqrt((temp_v[1] + temp_v[0]) + temp_v[2]);
          double d_vmag_rlen = vmag - rlen;
          pe += fcon * d_vmag_rlen;
          d_vmag_rlen = (fcon * d_vmag_rlen) / vmag;
          float d_fcon[3] = {(float) d_vmag_rlen, (float) d_vmag_rlen, (float) d_vmag_rlen};
          int sse_fx = _mm_mul_ps(_mm_load_ps(d_fcon), sse_p);
          _mm_store_ps(temp_v, sse_fx);
          fx[(nx * n) + ny] += temp_v[0];
          fy[(nx * n) + ny] += temp_v[1];
          fz[(nx * n) + ny] += temp_v[2];
        }

      }

    }

  }

  return pe;
}

