  #pragma omp target device(GPU_DEVICE)
  #pragma omp target map(to : a[0 : SIZE *SIZE]) map(tofrom : b[0 : SIZE *SIZE])
  {
    #pragma omp parallel for
    for (k = 0; k < s; ++k)
    {
      for (j = k; j < s; ++j)
      {
        sum = 0.0;
        for (i = 0; i < k; ++i)
        {
          sum += b[(j * s) + i] * b[(i * s) + k];
        }

        b[(j * s) + k] = a[(j * s) + k] - sum;
      }

      for (i = k + 1; i < s; ++i)
      {
        sum = 0.0;
        for (j = 0; j < k; ++j)
        {
          sum += b[(k * s) + j] * b[(i * s) + i];
        }

        b[(k * s) + i] = (a[(k * s) + i] - sum) / b[(k * s) + k];
      }

    }

  }
}

