int getNeighbors(int **grid, int i, int j)
{
  int neighborLin;
  int neighborCol;
  int alive = 0;
  for (neighborLin = i - 1; neighborLin <= (i + 1); neighborLin++)
  {
    for (neighborCol = j - 1; neighborCol <= (j + 1); neighborCol++)
    {
      if ((neighborLin != i) || (neighborCol != j))
      {
        switch (neighborLin)
        {
          case -1:
            switch (neighborCol)
          {
            case -1:
              alive += grid[2048 - 1][2048 - 1];
              break;

            case 2048:
              alive += grid[2048 - 1][0];
              break;

            default:
              alive += grid[2048 - 1][neighborCol];

          }

            break;

          case 2048:
            switch (neighborCol)
          {
            case -1:
              alive += grid[0][2048 - 1];
              break;

            case 2048:
              alive += grid[0][0];
              break;

            default:
              alive += grid[0][neighborCol];

          }

            break;

          default:
            switch (neighborCol)
          {
            case -1:
              alive += grid[neighborLin][2048 - 1];
              break;

            case 2048:
              alive += grid[neighborLin][0];
              break;

            default:
              alive += grid[neighborLin][neighborCol];

          }


        }

      }

    }

  }

  return alive;
}

