static int isLegalUTF8_char(const u8 *source, int length)
{
  u8 a;
  int len;
  const u8 *srcptr;
  if ((*source) < 0xC0)
    return 1;

  len = exBytesUTF8[(*source) & 0x3f];
  srcptr = source + len;
  if ((len + 1) > length)
    return -1;

  switch (len)
  {
    default:
      return -1;

    case 4:
      if (((a = *(--srcptr)) < 0x80) || (a > 0xBF))
      return -1;


    case 3:
      if (((a = *(--srcptr)) < 0x80) || (a > 0xBF))
      return -1;


    case 2:
      if (((a = *(--srcptr)) < 0x80) || (a > 0xBF))
      return -1;

      switch (*source)
    {
      case 0xE0:
        if (a < 0xA0)
        return -1;

        break;

      case 0xED:
        if (a > 0x9F)
        return -1;

        break;

      case 0xF0:
        if (a < 0x90)
        return -1;

        break;

      case 0xF4:
        if (a > 0x8F)
        return -1;


    }


    case 1:
      if (((*source) >= 0x80) && ((*source) < 0xC2))
      return -1;


  }

  if ((*source) > 0xF4)
    return -1;

  return len + 1;
}

