void create_histogram(int *hist, int **img, int num_rows, int num_cols)
{
  int cur_sum = 0;
  for (int i = 0; i < 256; i++)
    hist[i] = 0;

  for (int i = 1; i < (num_rows - 1); i++)
  {
    cur_sum = 0;
    for (int j = 1; j < (num_cols - 1); j++)
    {
      cur_sum = 0;
      if (img[i][j] < img[i - 1][j - 1])
        cur_sum += 128;

      if (img[i][j] < img[i - 1][j])
        cur_sum += 64;

      if (img[i][j] < img[i - 1][j + 1])
        cur_sum += 32;

      if (img[i][j] < img[i][j + 1])
        cur_sum += 16;

      if (img[i][j] < img[i + 1][j + 1])
        cur_sum += 8;

      if (img[i][j] < img[i + 1][j])
        cur_sum += 4;

      if (img[i][j] < img[i + 1][j - 1])
        cur_sum += 2;

      if (img[i][j] < img[i][j - 1])
        cur_sum += 1;

      hist[cur_sum]++;
    }

  }

}

