double angle_radians(double x, double y)
{
  double xu;
  double yu;
  double ang;
  xu = fabs(x);
  yu = fabs(y);
  if ((xu == 0) && (yu == 0))
    return 0;

  ang = atan(yu / xu);
  if (x >= 0)
  {
    if (y >= 0)
      return ang;
    else
      return (2 * M_PI) - ang;

  }
  else
  {
    if (y >= 0)
      return M_PI - ang;
    else
      return M_PI + ang;

  }

}

