  dist[6] = 0.066;
  dist[7] = 0.055;
  dist[8] = 0.008;
  dist[9] = 0.015;
  dist[10] = 0.025;
  dist[11] = 0.013;
  double roll = LCG_random_double(seed);
  for (int i = 0; i < 12; i++)
  {
    double running = 0;
    for (int j = i; j > 0; j--)
      running += dist[j];

    if (roll < running)
      return i;

  }

  return 0;
}


