void evolve(life_t *life)
{
  int x;
  int y;
  int i;
  int j;
  int r;
  int c;
  int alive_neighbs;
  int ncols = life->ncols;
  int nrows = life->nrows;
  #pragma omp parallel for private(alive_neighbs, y, i, j, r, c)
  for (x = 0; x < nrows; x++)
    for (y = 0; y < ncols; y++)
  {
    alive_neighbs = 0;
    for (i = x - 1; i <= (x + 1); i++)
      for (j = y - 1; j <= (y + 1); j++)
    {
      c = (i + nrows) % nrows;
      r = (j + ncols) % ncols;
      if ((!((i == x) && (j == y))) && (life->grid[c][r] == ALIVE))
        alive_neighbs++;

    }


    life->next_grid[x][y] = ((alive_neighbs == 3) || ((alive_neighbs == 2) && (life->grid[x][y] == ALIVE))) ? (ALIVE) : (DEAD);
  }


  swap_grids(&life->grid, &life->next_grid);
}


