static void pbkdf2(unsigned int _key[])
{
  sph_sha1_context ctx1;
  sph_sha1_context ctx2;
  sph_sha1_context tmp_ctx1;
  sph_sha1_context tmp_ctx2;
  unsigned char ipad[64];
  unsigned char opad[64];
  unsigned int tmp_hash[20 / 4];
  unsigned i;
  unsigned j;
  unsigned char *key = (unsigned char *) _key;
  for (i = 0; i < 16; i++)
  {
    ipad[i] = key[i] ^ 0x36;
    opad[i] = key[i] ^ 0x5C;
  }

  memset(&ipad[16], 0x36, (sizeof(ipad)) - 16);
  memset(&opad[16], 0x5C, (sizeof(opad)) - 16);
  sph_sha1_init(&ctx1);
  sph_sha1_init(&ctx2);
  sph_sha1(&ctx1, ipad, 64);
  sph_sha1(&ctx2, opad, 64);
