void prod_mat_vec_omp(sparse_matrix_t *A, vector_t *X, vector_t *Y)
{
  assert(A->N == X->N);
  assert(Y->N == X->N);
  int i;
  int j;
  int k;
  double accu;
  #pragma omp parallel for schedule(runtime) private(i,k,j,accu)
  for (i = 0; i < A->N; i++)
  {
    accu = 0.;
    for (k = 0; k < A->ncol[i]; k++)
    {
      j = A->col[i][k];
      accu += A->elt[i][k] * X->elt[j];
    }

    Y->elt[i] = accu;
  }

}


