item_t select_ith(item_t *vec, int len, int ith)
{
  if (len == 1)
    return vec[0];

  if (len == 2)
  {
    if (vec[0].sop > vec[1].sop)
    {
      item_t t = vec[0];
      vec[0] = vec[1];
      vec[1] = t;
    }

    return vec[ith];
  }

  int idx = 0;
  while ((idx == 0) || (idx == len))
  {
    item_t pivot = pick_pivot(vec, len);
    idx = partition(vec, len, pivot.sop);
    if ((idx == 0) || (idx == len))
      continue;

  }

  if (ith < idx)
  {
    return select_ith(vec, idx, ith);
  }
  else
  {
    return select_ith(vec + idx, len - idx, ith - idx);
  }

}


