int partition(item_t *vec, int len, double ref)
{
  int i = -1;
  int j = len;
  while (i < j)
  {
    while ((i < j) && (vec[++i].sop < ref))
    {
      if (i >= len)
        break;

    }

    while ((j > i) && (vec[--j].sop >= ref))
    {
    }

    if (i >= j)
      break;

    item_t t = vec[i];
    vec[i] = vec[j];
    vec[j] = t;
  }

  return i;
}

