void read_png_file(char *filename, char *outputFile)
{
  int width;
  int height;
  int color_type;
  int bit_depth;
  int *row_pointers = 0;
  int maskDimensions;
  int **maskMatrix;
  FILE *fp = fopen(filename, "rb");
  int png = png_create_read_struct(PNG_LIBPNG_VER_STRING, 0, 0, 0);
  if (!png)
    abort();

  int info = png_create_info_struct(png);
  if (!info)
    abort();

  if (setjmp(png_jmpbuf(png)))
    abort();

  png_init_io(png, fp);
  png_read_info(png, info);
  width = png_get_image_width(png, info);
  height = png_get_image_height(png, info);
  color_type = png_get_color_type(png, info);
  bit_depth = png_get_bit_depth(png, info);
  if (bit_depth == 16)
    png_set_strip_16(png);

  if (color_type == 0)
    png_set_palette_to_rgb(png);

  if ((color_type == PNG_COLOR_TYPE_GRAY) && (bit_depth < 8))
    png_set_expand_gray_1_2_4_to_8(png);

  if (png_get_valid(png, info, PNG_INFO_tRNS))
    png_set_tRNS_to_alpha(png);

  if (((color_type == PNG_COLOR_TYPE_RGB) || (color_type == PNG_COLOR_TYPE_GRAY)) || (color_type == 0))
    png_set_filler(png, 0xFF, PNG_FILLER_AFTER);

  if ((color_type == PNG_COLOR_TYPE_GRAY) || (color_type == PNG_COLOR_TYPE_GRAY_ALPHA))
    png_set_gray_to_rgb(png);

  png_read_update_info(png, info);
  row_pointers = (int *) malloc((sizeof(int)) * height);
  for (int y = 0; y < height; y++)
  {
    row_pointers[y] = (int *) malloc(png_get_rowbytes(png, info));
  }

  png_read_image(png, row_pointers);
  fclose(fp);
  png_destroy_read_struct(&png, &info, 0);
  int minRed = 255;
  int maxRed = 0;
  int minGreen = 255;
  int maxGreen = 0;
  int minBlue = 255;
  int maxBlue = 0;
  for (int i = 0; i < height; i++)
  {
    int row = row_pointers[i];
    for (int j = 0; j < width; j++)
    {
      int px = &row[j * 4];
      if (px[0] < minRed)
        minRed = px[0];

      if (px[0] > maxRed)
        maxRed = px[0];

      if (px[1] < minGreen)
        minGreen = px[1];

      if (px[1] > maxGreen)
        maxGreen = px[1];

      if (px[2] < minBlue)
        minBlue = px[2];

      if (px[2] > maxBlue)
        maxBlue = px[2];

    }

  }

  int preComputationRed = 255 / (maxRed - minRed);
  int preComputationGreen = 255 / (maxGreen - minGreen);
  int preComputationBlue = 255 / (maxBlue - minBlue);
  for (int i = 0; i < height; i++)
  {
    int row = row_pointers[i];
    for (int j = 0; j < width; j++)
    {
      int px = &row[j * 4];
      px[0] = preComputationRed * (px[0] - minRed);
      if (px[0] < 0)
        px[0] = 0;

      if (px[0] > 255)
        px[0] = 255;

      px[1] = preComputationGreen * (px[1] - minGreen);
      if (px[1] < 0)
        px[1] = 0;

      if (px[1] > 255)
        px[1] = 255;

      px[2] = preComputationBlue * (px[2] - minBlue);
      if (px[2] < 0)
        px[2] = 0;

      if (px[2] > 255)
        px[2] = 255;

    }

  }

  fp = fopen(outputFile, "wb");
  if (!fp)
    abort();

  png = png_create_write_struct(PNG_LIBPNG_VER_STRING, 0, 0, 0);
  if (!png)
    abort();

  info = png_create_info_struct(png);
  if (!info)
    abort();

  if (setjmp(png_jmpbuf(png)))
    abort();

  png_init_io(png, fp);
  png_set_IHDR(png, info, width, height, 8, PNG_COLOR_TYPE_RGBA, PNG_INTERLACE_NONE, PNG_COMPRESSION_TYPE_DEFAULT, PNG_FILTER_TYPE_DEFAULT);
  png_write_info(png, info);
  if (!row_pointers)
    abort();

  png_write_image(png, row_pointers);
  png_write_end(png, 0);
  for (int y = 0; y < height; y++)
  {
    free(row_pointers[y]);
  }

  free(row_pointers);
  fclose(fp);
  png_destroy_write_struct(&png, &info);
}

