double calc_error(double a, double b, double c, double d, double e)
{
  double total_sq_err = 0.0;
  register int f;
  for (f = 0; f < 245; f++)
  {
    double x = important[f];
    double expec = expected[f];
    double calculated = x * ((x * ((x * ((x * ((x * a) + b)) + c)) + d)) + e);
