void receive_halos(float *BuffUP, float *BuffLW, const int BuffSZ, const int rank, const int nranks, MPI_Request *req)
{
  const int up = rank - 1;
  const int lw = rank + 1;
  if (rank > 0)
    MPI_Irecv(BuffUP, BuffSZ, (MPI_Datatype) 0x4c00040a, up, 0, (MPI_Comm) 0x44000000, &req[0]);
  else
    req[0] = (MPI_Request) 0x2c000000;

  if (rank < (nranks - 1))
    MPI_Irecv(BuffLW, BuffSZ, (MPI_Datatype) 0x4c00040a, lw, 1, (MPI_Comm) 0x44000000, &req[1]);
  else
    req[1] = (MPI_Request) 0x2c000000;

}


void send_halos(float *HaloUP, float *HaloLW, const int BuffSZ, const int rank, const int nranks, MPI_Request *req)
{
  const int up = rank - 1;
  const int lw = rank + 1;
  if (rank < (nranks - 1))
    MPI_Isend(HaloLW, BuffSZ, (MPI_Datatype) 0x4c00040a, lw, 0, (MPI_Comm) 0x44000000, &req[3]);
  else
    req[3] = (MPI_Request) 0x2c000000;

  if (rank > 0)
    MPI_Isend(HaloUP, BuffSZ, (MPI_Datatype) 0x4c00040a, up, 1, (MPI_Comm) 0x44000000, &req[2]);
  else
    req[2] = (MPI_Request) 0x2c000000;

}


void wait_exchange_halos(float *HaloFromUP, float *HaloFromLW, float *BuffUP, float *BuffLW, const int BuffSZ, const int rank, const int nranks, MPI_Request *req)
{
  MPI_Status statuses[4];
  MPI_Waitall(4, req, statuses);
  int i;
  if (rank > 0)
  {
    #pragma omp parallel for
    for (i = 0; i < BuffSZ; i++)
      HaloFromUP[i] = BuffUP[i];

  }

  if (rank < (nranks - 1))
  {
    #pragma omp parallel for
    for (i = 0; i < BuffSZ; i++)
      HaloFromLW[i] = BuffLW[i];

  }

}

