  else
    t_mms = missmatchScore;

  diag = H[(index - m) - 1] + t_mms;
  int max = 0;
  int pred = 0;
  if (diag > max)
  {
    max = diag;
    pred = 3;
  }

  if (up > max)
  {
    max = up;
    pred = 1;
  }

  if (left > max)
  {
    max = left;
    pred = 2;
  }

  H[index] = max;
  P[index] = pred;
  if (max > H[maxPos_ptr[0]])
  {
    maxPos_ptr[0] = index;
  }

}

