          uint_fast32_t lookahead2 = (bit | (new_diagl << (3 - 1))) | (new_diagr >> (3 - 1));
          uint_fast32_t allowed2 = l_rest > ((int8_t) 0);
          if (allowed2 && ((lookahead2 == UINT_FAST32_MAX) || (lookahead1 == UINT_FAST32_MAX)))
          {
