          posibs[d] = posib;
          d += posib != UINT_FAST32_MAX;
          posib = new_posib;
          l_rest--;
          cols[d] = bit;
          diagl[d] = new_diagl << 1;
          diagr[d] = new_diagr >> 1;
          rest[d] = l_rest;
        }
        else
        {
          num += bit == UINT_FAST32_MAX;
        }

      }

      d--;
      posib = posibs[d];
    }

  }

  return num * 2;
