int lower_bound(int array[], int low, int high, int key)
{
  if (key <= array[low])
  {
    return 0;
  }

  if (key > array[high - 1])
  {
    return high - low;
  }

  int l = low;
  while (low < high)
  {
    int mid = (low + high) / 2;
    if (key <= array[mid])
    {
      high = mid;
    }
    else
    {
      low = mid + 1;
    }

  }

  return low - l;
}

