uint64_t countPrimes(uint64_t rangeStart, uint64_t rangeEnd, uint64_t nth, uint64_t *thePrime)
{
  if (thePrime != 0)
    printf("- Counting the primes in %u..%u and finding the %u%s ...\n", rangeStart, rangeEnd, nth, ordinal(nth));
  else
    printf("- Counting the primes in %u..%u ...\n", rangeStart, rangeEnd);

  uint32_t crossingMax = (uint32_t) ceil(sqrt((double) rangeEnd));
  uint32_t crossingPrimesCount;
  uint32_t *crossingPrimes = primesTable(crossingMax, &crossingPrimesCount);
  printf("\tUsing %d primes (%d..%d) for crossing off\n", crossingPrimesCount, crossingPrimes[0], crossingPrimes[crossingPrimesCount - 1]);
  uint64_t primeCount = 0;
  if (rangeStart < 3)
  {
    ++primeCount;
    --nth;
    if ((thePrime != 0) && (nth == 0))
      *thePrime = 2;

    rangeStart = 3;
  }

  rangeStart = (rangeStart + 1) - (rangeStart % 2);
  if (rangeStart >= rangeEnd)
    return primeCount;

  uint64_t range = rangeEnd - rangeStart;
  uint8_t * const isPrime = malloc((range + 1) / 2);
  memset(isPrime, 1, (range + 1) / 2);
  for (uint32_t i = 1; i < crossingPrimesCount; ++i)
  {
    uint64_t prime = crossingPrimes[i];
    uint64_t rangeStartAdjusted = rangeStart + ((prime - (rangeStart % prime)) % prime);
    if ((rangeStartAdjusted % 2) == 0)
      rangeStartAdjusted += prime;

    if (rangeStartAdjusted < (prime * prime))
      rangeStartAdjusted = prime * prime;

    for (uint64_t j = rangeStartAdjusted; j < rangeEnd; j += 2 * prime)
      isPrime[(j - rangeStart) / 2] = 0;

  }

  for (uint64_t j = rangeStart; j < rangeEnd; j += 2)
  {
    if (isPrime[(j - rangeStart) / 2])
    {
      ++primeCount;
      if ((thePrime != 0) && ((--nth) == 0))
        *thePrime = j;

    }

  }

  printf("\t%u primes found\n", primeCount);
  free(crossingPrimes);
  free(isPrime);
  return primeCount;
}

