void activateNN(double *input)
{
  #pragma omp parallel for
  for (int i = 0; i < 100; i++)
  {
    double ins = 0.0;
    #pragma omp simd reduction(+:ins)
    for (int j = 0; j < (784 + 1); j++)
    {
      ins += WL1[i][j] * input[j];
    }

    DL1[i] = ins;
    OL1[i] = 1.0 / (1 + exp(-ins));
  }

  OL1[100] = 0.5;
  #pragma omp parallel for
  for (int i = 0; i < 10; i++)
  {
    double ins = 0.0;
    #pragma omp simd reduction(+:ins)
    for (int j = 0; j < (100 + 1); j++)
    {
      ins += WL2[i][j] * OL1[j];
    }

    DL2[i] = ins;
    OL2[i] = 1.0 / (1 + exp(-ins));
  }

}


void trainNN(double *input, double *desired)
{
  double delta[10];
  #pragma omp parallel for
  for (int i = 0; i < 10; i++)
  {
    double temp_delta = (OL2[i] * (1 - OL2[i])) * (desired[i] - OL2[i]);
    delta[i] = temp_delta;
    #pragma omp simd
    for (int j = 0; j < (100 + 1); j++)
    {
      WL2[i][j] = WL2[i][j] + ((0.05 * temp_delta) * OL1[j]);
    }

  }

  #pragma omp parallel for
  for (int i = 0; i < 100; i++)
  {
    double temp_delta = OL1[i] * (1 - OL1[i]);
    double sum = 0.0;
    for (int j = 0; j < 10; j++)
    {
      sum += delta[j] * WL2[j][i];
    }

    temp_delta *= sum;
    #pragma omp simd
    for (int j = 0; j < (784 + 1); j++)
    {
      WL1[i][j] = WL1[i][j] + ((0.05 * temp_delta) * input[j]);
    }

  }

}

